import{M as n,r as i}from"./manifest-ritual-sources-b82wbTvz.js";import{m as s,a as r}from"./manifestTechniqueLesson-CM64EG9q.js";const c=[{number:13,technique:"Pillow method",title:"Pillow method: give the note a waking job",goal:"Keep the bedtime note and connect it to a waking action.",hook:"A wish under your pillow can stay. Give the note something useful to remind you of tomorrow.",reason:"Would daytime planning leave more room for sleep?",paragraphs:["The pillow method means placing a written wish under your pillow. A common recipe is to write it as already true, fold the paper, place it underneath, then repeat or imagine the outcome before sleep. That paper delivering an external result is not supported by the evidence reviewed. [manifest-P08, manifest-T19]","ODA version: keep the note, add a specific goal and likely obstacle, then write an if-then plan for one action. Specific cue-and-response plans have research support; special bedtime attraction does not. Do one useful act today, review tomorrow, and leave further planning for daytime if it keeps you awake. [manifest-T02, manifest-T19]"],example:{title:"The morning message",text:"At her kitchen table, Maya writes a job wish and sends one tailored application. Her pillow note adds: if breakfast dishes are cleared, check a new suitable vacancy. Next morning she checks it and starts another application. It needs more detail. Her record keeps the submission and unfinished draft separate; no employer has replied."},instructions:["Keep the note; add your goal and obstacle before settling for sleep.","Write an if-then cue and do one useful action today.","Tomorrow, review the attempted action separately from the pillow ritual."],action:["Send one tailored application","Ask one contact about an opening"],minimum:["Submit one suitable application","Send one specific question"],cue:["After clearing breakfast dishes","After today's lunch break"],place:["At the kitchen table","At my usual workspace"],obstacle:"Bedtime planning keeps me awake",fallback:["Plan during tomorrow's lunch break","Use a daytime note instead"],observation:["Application submitted; reply still unknown","Question sent; response recorded separately"],stopRule:"Stop if the ritual delays sleep. Move planning to daytime; no bedtime repetition is required.",scenario:"Maya's note names a morning question about a suitable vacancy. Rewriting it at bedtime keeps her awake, although tomorrow's cue is already clear.",question:"What should she do tonight?",options:[{key:"a",text:"Rewrite the note once more, then decide tomorrow whether the vacancy question still feels right.",feedback:"Another rewrite costs sleep without adding a needed detail. Her cue is clear already. Keep the planned question and move any further editing to daytime."},{key:"b",text:"Leave the note alone, let herself sleep, and ask about the vacancy at her waking cue.",feedback:"This protects sleep and preserves the useful commitment. Tomorrow she can record whether she sent the question, while keeping an employer's reply separate from her action."},{key:"c",text:"Replace the morning follow-up with a longer daytime visualization of the employer's reply.",feedback:"Daytime is a better place for extended planning, but this replaces an available useful act. Imagining a reply does not send the message or establish what the employer will decide."}],best:"b",takeaway:"Keep the pillow note brief and give its action a waking cue.",review:"What action did you attempt after the note, and did bedtime planning interfere with sleep?",deeper:[{heading:"The familiar pillow recipe",paragraphs:["1. Choose a desired outcome and write one present-tense line, such as an imagined offer already received. This follows a practitioner recipe; the line records a wish rather than verified news. You can keep the wording private. [manifest-P08]","2. Fold the paper and place it under your pillow. The guide includes additional writing and folding details, but these describe that author's variant. They are not established requirements for an external result. Use an ordinary note you already have. [manifest-P08]","3. Read or mentally repeat the line while settling into bed. Imagine the outcome as fulfilled if you enjoy that part. Then let yourself sleep; do not make vivid imagery, repetition or a particular feeling a condition for stopping. [manifest-P08]","4. Revisit the note on another evening if wanted. The guide documents a recognizable ritual, not controlled efficacy evidence. A review of arousal circuits does not establish that bedtime wishes bypass critical thought or make outside events happen. [manifest-P08, manifest-T19]"]},{heading:"A note with a waking job",paragraphs:["Add a small practical instruction before you get into bed. Write the specific goal, the obstacle you expect, and the action you can actually take. For a job search: 'If breakfast is cleared, I will submit one suitable application. If the form is confusing, I will ask the recruiter one specific question.' Keep uncertain outcomes, such as an offer, separate from the action. [manifest-T02]","Gollwitzer and Sheeran's meta-analysis found an average goal-attainment benefit from specific if-then plans across varied settings. It did not test paper under pillows or establish that planning removes effort. The arousal review describes interacting wakefulness circuits, not a subconscious route for delivering wishes. These are different claims. [manifest-T02, manifest-T19]","ODA adds today's attempt and tomorrow's review as practical choices, not a tested bedtime package. Record what you sent, asked or completed; record any response separately. If editing the note keeps you awake, leave it and choose a daytime opportunity. Your next useful act does not require finishing the ritual. [manifest-T02, manifest-P08]"]}],sources:["manifest-P08","manifest-T02","manifest-T19"]},{number:14,technique:"Whisper method",title:"Whisper method: rehearse a request you can make",goal:"Turn an imagined exchange into one respectful request under your control.",hook:"Waiting for someone to text back? The whisper ritual can help you choose your own next step.",reason:"Is there an appropriate request I can make?",paragraphs:["The whisper method is an imagined request to another person. In a common recipe, relax, picture approaching them, whisper what you want three times, then leave the scene. Remotely making that person respond is not supported by the evidence reviewed. Their consent and boundaries still matter. [manifest-P09]","ODA version: keep the private whisper, choose a specific goal and name the obstacle. Rehearse a respectful request, including room for refusal. Write an if-then plan for one appropriate action today, then review your action tomorrow. Cue-and-response planning has support; feeling certain about someone else's response is not evidence that they will agree. [manifest-T02, manifest-T13]"],example:{title:"Asking without pushing",text:"At lunch, Ben imagines whispering a request for a project meeting. He changes it to a sentence he can send: 'Could we talk for ten minutes Thursday?' His colleague replies that Thursday is full. Ben records the message and refusal, then asks whether next week suits. His ritual did not obligate her to agree."},instructions:["Whisper a respectful request privately; leave room for the person to decline.","Name your goal, obstacle and if-then plan; make one appropriate request today.","Tomorrow, review what you asked and how you respected the response."],action:["Ask for a brief project meeting","Send one appropriate availability question"],minimum:["Send one clear meeting request","Ask one relevant question"],cue:["After today's lunch break","When the agreed check-in begins"],place:["At my work desk","In our usual meeting space"],obstacle:"I keep editing a simple request",fallback:["Use one plain request sentence","Ask at the agreed check-in"],observation:["Request made; answer recorded separately","Boundary respected; next step chosen"],stopRule:"Do not contact someone who has declined contact. Private imagery cannot override another person's boundaries.",scenario:"Ben wants a meeting. His colleague has said this week is full but invited him to ask about next week. His whisper practice feels reassuring.",question:"Which next move fits the information he has?",options:[{key:"a",text:"Ask once about next week's availability, then accept the answer without repeated messages.",feedback:"She offered that opening, so one clear question respects it. He can record the request and response separately. His reassurance gives him no claim over her time."},{key:"b",text:"Wait for her to suggest a time because the imagined exchange now feels complete.",feedback:"Waiting may be his choice, but the imagined exchange did not ask about next week. Her invitation gives him a suitable opening for one real request if the meeting still matters."},{key:"c",text:"Send a warmer explanation of why this week's meeting would mean so much to him.",feedback:"A warmer message still asks her to reconsider the week she ruled out. Use the opening she actually offered, rather than making stronger feelings a reason to press her."}],best:"a",takeaway:"Rehearse your request; another person's answer remains theirs.",review:"What request did you actually make, and how did you respond to their answer or boundary?",deeper:[{heading:"The popular imagined exchange",paragraphs:["1. Pick the person and desired response. In the practitioner account, the exercise happens in imagination. Choosing a response describes what you want; it does not show what that person wants or establish permission to contact them. [manifest-P09]","2. Relax and picture that person in a setting. Imagine approaching them and whispering the request in their ear three times. The count is part of this recipe, not a scientifically established dose for influencing someone. Eyes-open or verbal description can be your adaptation. [manifest-P09]","3. Leave the imagined scene. Some variants add a pictured forehead kiss, which is another scene detail rather than evidence of remote influence. In ODA, keep any exercise private and choose a request you could make respectfully. Do not treat imagined intimacy as consent. [manifest-P09]","4. Decide whether an actual request is appropriate. The practitioner story documents the ritual but cannot demonstrate telepathy or control. A person may decline, stay silent or change their mind; repeated whispers do not create an obligation to respond. [manifest-P09]"]},{heading:"Plan your side of the conversation",paragraphs:["Keep the goal specific: asking for an available meeting is different from making someone admire you. Name an obstacle you can respond to, such as delaying a short message through repeated editing. Then choose a cue: 'If my lunch break ends, I will send one clear availability question.' If contact is unwelcome, your action can be respecting that boundary. [manifest-T02, manifest-P09]","Implementation-intention research supports connecting a detectable situation with a chosen response. It does not establish control over the recipient. In three online survey samples, Dixon and colleagues found manifestation belief associated with confidence and some reported financial risks. Those associations do not establish causation, and that study did not test whispering. Feeling certain is not a measurement of someone else's agreement. [manifest-T02, manifest-T13]","ODA's private rehearsal and next-day return are adaptations. Make one appropriate request today or save an agreed opportunity. Tomorrow, write what you actually asked, any answer received, and whether you respected it. Silence stays unknown. Choose another appropriate step or stop; do not count the imagined exchange as the real conversation. [manifest-T02, manifest-P09]"]}],sources:["manifest-P09","manifest-T02","manifest-T13"]},{number:18,technique:"17-second focus",title:"17-second focus: let the timer cue an action",goal:"Use a preferred pause to cue action, without a scientific timing claim.",hook:"Your mind wandered before seventeen seconds. That does not cancel your chance to take the next step.",reason:"Does the timer help me start or delay?",paragraphs:["The 17-second method means holding a desired thought without contradiction for seventeen seconds. Some versions repeat four intervals, totaling sixty-eight seconds. The special timing and attraction threshold are not supported by the evidence reviewed. Priming research does not validate those counts or deliberate wish rituals. [manifest-P13, manifest-T16]","ODA version: keep seventeen seconds as a preferred pause, then name a specific goal and obstacle. Write an if-then plan for one action today and review the attempt tomorrow. Specific planning has research support. A wandering thought is no reason to restart before acting; the timer is your cue, not a requirement for getting results. [manifest-T02, manifest-P13]"],example:{title:"The interrupted pause",text:"Before lunch, Aisha sets a seventeen-second timer for her portfolio goal. A delivery interrupts her thought. She leaves the timer alone and follows her plan: after lunch, send one work sample to a suitable client. The client asks for a different style. Aisha records the message and the feedback rather than restarting her focus exercise."},instructions:["Choose your goal; use seventeen seconds as an optional pause.","Name an obstacle and if-then plan; take one useful action today.","Review the attempted action tomorrow, including any feedback you received."],action:["Send a relevant work sample","Request feedback on one draft"],minimum:["Send one suitable sample","Ask one specific feedback question"],cue:["After today's lunch","When the optional timer ends"],place:["At my usual workspace","At the library desk"],obstacle:"I restart whenever my attention wanders",fallback:["Skip the timer and send","Use a written action cue"],observation:["Sample sent; reply recorded separately","Question asked; feedback still unknown"],stopRule:"Skip the timer if restarting delays action or feels distressing. Unwanted thoughts require no ritual correction.",scenario:"Aisha's prepared sample fits a client's request. A notification interrupted her focus timer. She has five minutes to send the sample before a meeting.",question:"What makes best use of this opening?",options:[{key:"a",text:"Repeat the focus once without notifications, then send if enough time remains before the meeting.",feedback:"Removing notifications can help a preferred pause, but the available task is already clear. Making another uninterrupted interval a condition risks losing the useful opening she has now."},{key:"b",text:"Save both the focus exercise and sample message for a longer uninterrupted session tomorrow.",feedback:"A later appointment can fit a task that needs more time. Here the sample is prepared and five minutes are available; an interrupted ritual does not require postponing the message."},{key:"c",text:"Send the prepared sample now and record the message separately from the interrupted focus pause.",feedback:"This uses the available opening and keeps an honest record. The sample was sent; the pause was interrupted. Neither fact tells her what the client will decide."}],best:"c",takeaway:"Let the timer cue your action rather than set a condition for it.",review:"What useful action did you attempt, and did the timer help you start or delay?",deeper:[{heading:"What the seventeen-second recipe asks",paragraphs:["1. Choose a desired experience or positive thought. The teaching attributed to Abraham through Esther and Jerry Hicks asks for attention to that thought without an opposing thought. This describes the ritual rather than a research-tested procedure. [manifest-P13]","2. Hold the thought for seventeen seconds. Some versions extend through four consecutive intervals, giving sixty-eight seconds. You can use a timer if you want the recognizable format, but the inspected evidence does not establish a special attraction threshold at either duration. [manifest-P13, manifest-T16]","3. Notice whether attention wandered, without turning that into a verdict on your future. ODA removes restarting as a condition for action. The teacher's claims about thoughts changing reality or equaling many hours of work are not findings from the research reviewed. [manifest-P13]","4. End the pause and choose your next act. Experimental priming concerns cues studied in particular conditions; it is not the same as this deliberate timed wish. A preferred interval can remain part of your ritual without acquiring scientific authority. [manifest-T16, manifest-P13]"]},{heading:"Use the end as a start cue",paragraphs:["Pick one action before the timer begins. For a portfolio goal, that might be sending one suitable work sample today. Name the obstacle: restarting until focus feels perfect. Then write, 'If the timer ends, I will send the prepared sample, even if my attention wandered.' If a timer adds pressure, use another visible cue instead. [manifest-T02]","Gollwitzer and Sheeran's meta-analysis supports specific if-then planning on average across varied tasks. Dai and colleagues' priming review found an average effect overall, but smaller, statistically inconclusive effects in its limited preregistered subset. That uncertainty does not disprove all priming. Neither review validates seventeen seconds, sixty-eight seconds or a rule that unwanted thoughts block outcomes. [manifest-T02, manifest-T16]","The ODA pause-and-action sequence is an adaptation, not either research protocol. Tomorrow, record the action attempted and any outside feedback separately from the quality of your focus. Did the pause provide a workable cue, or did repeated attempts consume the opening? Keep, shorten or drop the timer according to that practical record. [manifest-T02, manifest-P13]"]}],sources:["manifest-P13","manifest-T02","manifest-T16"]},{number:19,technique:"Box method",title:"Box method: give one wish an action date",goal:"Keep the wish box and take one feasible step toward a specific goal.",hook:"Your box holds things you want. Which card gets an action today?",reason:"Which wish fits my time and resources today?",paragraphs:["The box method stores written wishes, pictures or meaningful objects in a container. A common recipe is to choose a box, add intentions and desired feelings, then revisit them while imagining fulfillment. A container delivering those wishes is not supported by the evidence reviewed. An existing box is enough. [manifest-P14]","ODA version: keep the cards. Add a specific goal, obstacle, if-then plan and one action today to a chosen card; review its actual attempt tomorrow. Contrasting a goal with obstacles and a response plan has research support, as does progress monitoring on average. This box adaptation is not a tested package. [manifest-T01, manifest-T03]"],example:{title:"One card leaves the box",text:"At the kitchen table, Luca puts a card for a weekend course into an old shoebox. He writes the obstacle, limited time, and calls the organizer to ask about attendance options. The course has no flexible option. Tomorrow he records the call and chooses a different course rather than adding more wishes to the box."},instructions:["Choose an existing container and one card with a specific goal.","Add an obstacle and if-then response; take one feasible action today.","Open that card tomorrow and record the actual attempted action."],action:["Ask about course attendance options","Request one relevant program detail"],minimum:["Send one specific course question","Make one useful inquiry"],cue:["After today's breakfast","When the office phone line opens"],place:["At the kitchen table","In my quiet work corner"],obstacle:"The schedule may not fit",fallback:["Ask about another attendance option","Contact one suitable alternative"],observation:["Inquiry sent; schedule answer recorded","Alternative contacted; response still unknown"],stopRule:"Use supplies you already have. If an option exceeds your resources, change the action or pause.",scenario:"Luca's course card names a schedule conflict. The organizer can answer questions today. He also has several new pictures he wants to add to the box.",question:"Which next move best tests whether this course fits?",options:[{key:"a",text:"Ask the organizer about attendance options, then write the answer on the course card.",feedback:"This tests the named obstacle and creates an actual record. The answer may rule out this course, which still helps Luca choose a feasible next step."},{key:"b",text:"Add the new pictures first so the box reflects the full experience he wants.",feedback:"The pictures can stay part of his preferred ritual. They do not answer the schedule question, though. Today's opening is a chance to learn whether the course is feasible."},{key:"c",text:"Choose a different course immediately, since the schedule conflict makes this one uncertain.",feedback:"A different course may fit better, but the organizer can clarify this uncertainty now. One specific inquiry gives him useful information before he decides whether to change the goal."}],best:"a",takeaway:"Keep the wish card, add a feasible action, and record what actually happened.",review:"What action did you attempt for the card, and what did you learn about its obstacle?",deeper:[{heading:"Build the familiar wish box",paragraphs:["1. Choose a box or container. The practitioner guide uses the box as a place for intentions. ODA asks you to use something already available, such as an old shoebox or envelope. Buying a special object is not part of the assignment. [manifest-P14]","2. Write wishes on cards or choose pictures representing them. The guide also includes why you want each outcome and how receiving it would feel. Keep those personal details private if you prefer; a plain label can preserve the format. [manifest-P14]","3. Put the cards or pictures inside. Return to the contents and imagine receiving the wishes if you enjoy that ritual. These steps describe a first-person practitioner's method, not evidence that the container creates an external event. [manifest-P14]","4. Choose one card to connect with a real opportunity. The guide's energy-field explanation is a belief rather than an established research finding. You can keep the symbolic container while changing what you do with a card today. [manifest-P14]"]},{heading:"Put the obstacle on the back",paragraphs:["Keep the wish or image on the front. On the back, write the goal in specific terms, a likely obstacle and an if-then response. For a course: 'If the organizer's phone line opens, I will ask about attendance options. If the schedule cannot work, I will inquire about one suitable alternative.' Choose a feasible action today rather than counting card-making as the inquiry. [manifest-T01]","Mental contrasting with implementation intentions links a wished-for outcome, a real obstacle and a response plan. Its meta-analysis found modest average support for goal attainment, with varied results and possible publication bias. Harkin and colleagues found average benefits from encouraging progress monitoring. Neither review tested a manifestation box or proved that tomorrow is the best review schedule. [manifest-T01, manifest-T03]","ODA's next-day return gives this card a practical review point. Record what you actually asked and what you learned; distinguish a sent inquiry from a useful reply or enrollment. Change the goal when money, access or time makes it infeasible. The box can hold a revised card, a paused goal or an honest unsuccessful attempt. [manifest-T01, manifest-T03]"]}],sources:["manifest-P14","manifest-T01","manifest-T03"]},{number:20,technique:"SATS: state akin to sleep",title:"SATS: let the scene end in sleep",goal:"Keep gentle imagery and rehearse a practical step without delaying sleep.",hook:"Repeating the perfect bedtime scene? You can stop and still take a useful step tomorrow.",reason:"Does this scene leave enough room for sleep?",paragraphs:["SATS, or state akin to sleep, is imagining a short fulfillment scene while relaxed and drowsy. Practitioners choose a scene implying success, imagine participating, and repeat it as real. Some let themselves fall asleep. Verdict: mixed for related imagery, not supported for drowsy wish delivery. Mental simulation supports behavior on average, without establishing a special bedtime advantage. [manifest-P15, manifest-T04, manifest-T19]","ODA version: keep gentle imagery. Name your specific goal and obstacle, write an if-then plan, then rehearse the first practical step. Take one action today and review tomorrow. The scene need not feel perfect. Stop if repetition keeps you awake; sleep is not a test of belief. [manifest-P15, manifest-T19]"],example:{title:"A scene with a limit",text:"At her desk, Nina sends a question about a training program. Before bed she briefly imagines attending, then rehearses asking about fees at tomorrow's lunch break. Repeating the scene makes her alert, so she stops. Next day she asks; the program costs too much. She records that answer and looks for a free option."},instructions:["Before settling, name your goal, obstacle and if-then plan on a note.","Rehearse the first step briefly; take one useful action today.","Let sleep take priority; review your actual attempted action tomorrow."],action:["Ask about a program's fees","Request one useful access detail"],minimum:["Send one specific fee question","Ask one access question"],cue:["After today's lunch break","When the program office opens"],place:["At my usual workspace","At the kitchen table"],obstacle:"Imagery keeps me awake",fallback:["Use a daytime verbal rehearsal","Skip imagery and ask directly"],observation:["Question asked; reply recorded separately","Sleep interference noticed; imagery stopped"],stopRule:"Stop if imagery increases wakefulness or distress. Use daytime rehearsal or skip it; protect sleep.",scenario:"Nina has a clear daytime plan to ask about fees. Her repeated SATS scene is keeping her alert, and it still does not feel fully real.",question:"What should she choose now?",options:[{key:"a",text:"Make the scene simpler and keep repeating until it feels convincing enough to end.",feedback:"Simplifying may suit a daytime rehearsal, but conviction is not a required stopping condition. Repetition is keeping her alert, so continuing puts the ritual ahead of sleep."},{key:"b",text:"Stop the scene, let herself sleep, and ask about fees at the daytime cue.",feedback:"Her practical cue is already clear. Stopping protects sleep without abandoning the goal. Tomorrow she can record the question she asked and any fee information she received."},{key:"c",text:"Replace the fee question with a longer daytime SATS session that feels easier to control.",feedback:"Daytime may fit optional imagery better, but a longer scene still does not answer the fee question. Keep the real inquiry and treat any rehearsal as preparation."}],best:"b",takeaway:"A brief scene can end before it feels perfect; the real attempt gets its own record.",review:"What action did you actually attempt, and did the imagery leave room for sleep?",deeper:[{heading:"The scene in the SATS teaching",paragraphs:["1. Choose an outcome and a short scene implying that it has happened. Neville Goddard's lectures describe participating in a fulfillment scene rather than watching yourself from outside. This is the teacher's method, not a demonstrated route for changing external events. [manifest-P15]","2. Sit or lie comfortably, close your eyes if wanted, and relax toward drowsiness. The source treats this state as part of the practice. ODA permits an eyes-open or verbal adaptation and does not ask you to force drowsiness. [manifest-P15]","3. Repeat the brief scene while imagining it as real. Some versions allow sleep to arrive in that feeling; others remain gently attentive. You can stop before the scene feels convincing. Do not keep yourself awake to achieve an imagined standard. [manifest-P15]","4. Leave metaphysical claims separate from the recipe. An arousal review describes interacting sleep and wakefulness circuits, not evidence that a drowsy state makes wishes real. Goddard's no-action-needed teaching is not a conclusion from mental-simulation research. [manifest-P15, manifest-T19, manifest-T04]"]},{heading:"Rehearse a step while protecting sleep",paragraphs:["Choose a specific goal and name the obstacle before settling down. For a training program, the goal might be checking whether fees fit your resources. Briefly rehearse asking the actual question, including what you will do if the answer rules the program out. This is ODA's practical adaptation; it need not reproduce Goddard's prescribed feeling or scene. [manifest-P15, manifest-T04]","Cole and colleagues' synthesis found an average behavioral benefit from mental simulation across varied studies, mostly with students. It did not establish a reliable ranking between simulation subtypes or a special bedtime advantage. The arousal review likewise does not show that drowsiness bypasses thought or delivers outside outcomes. General imagery evidence cannot validate every SATS claim. [manifest-T04, manifest-T19]","Use a daytime cue for the real question and make one useful inquiry today when appropriate. Tomorrow, record the inquiry and reply separately from the imagery. If the scene increases wakefulness, stop and choose daytime rehearsal or no imagery. The next action can remain scheduled even when you leave the scene unfinished. This full sequence has not been tested as a SATS intervention. [manifest-P15, manifest-T04, manifest-T19]"]}],sources:["manifest-P15","manifest-T04","manifest-T19"]}],l=[{number:6,technique:"3-6-9 method",title:"3-6-9: put your applications on the page",goal:"Keep the notebook and complete one step toward a specific target.",hook:"Writing “I got the job” again? Give the company on your other page an application.",reason:"Will this notebook lead to work you want, or take time from applying?",paragraphs:["The 3-6-9 method repeats a present-tense affirmation three times in the morning, six at noon, nine at night. In the two-page variant, desired companies go left and “I got the job” goes right. Not supported: special counts attracting an offer. A success story cannot separate repetitions from applications or show the unsuccessful attempts.","ODA version: keep the pages and optional rhythm. Left: specific targets plus today’s apply, follow-up, or preparation step. Right: a credible identity line and an if-then response to one obstacle. Specific cue-response plans have research support. Do one target action today; tomorrow review the act and any reply separately."],example:{title:"Maya uses both pages",text:"Maya lists two logistics companies on the left page and “I prepare useful applications” on the right. After lunch, she checks one vacancy and sends a tailored résumé. Her plan says, “If the portal fails, save the draft and contact recruitment.” One portal fails. She records the contact request; neither company has offered anything."},instructions:["Left page: name a target and today’s apply, follow-up, or preparation step.","Right page: add an identity line and an obstacle-response if-then plan.","Do the target action; review your attempt and any reply tomorrow."],action:["Send a tailored application","Send a company follow-up"],minimum:["Submit one suitable application","Send one follow-up question"],cue:["After lunch ends","When I finish the morning writing"],place:["At my application desk","In the company application portal"],obstacle:"The application portal will not load",fallback:["Save the draft and contact recruitment","Use another available application opening"],observation:["Submission or request, plus any reply","The application step I actually completed"],stopRule:"Skip repetitions that crowd out action; pause unaffordable or unsuitable applications.",scenario:"Maya wrote all 18 repetitions and listed three companies. One suitable vacancy closes tonight. Its application needs a short experience paragraph.",question:"What should her next notebook session produce?",options:[{key:"repeat",text:"Keep the affirmation schedule and prepare a longer identity statement before returning to the application.",feedback:"A statement can remain part of her ritual, but a longer one does not fill the application gap. With the deadline near, use the notebook to cue the required paragraph."},{key:"submit",text:"Write the required paragraph, submit the application, and record the submission separately from any employer reply.",feedback:"This matches the specific target and deadline. The submission is her action; a reply remains outside her control. Keep the ritual if she likes it, then review what actually happened."},{key:"expand",text:"Expand the company list first so tomorrow she can pursue a wider selection of potential jobs.",feedback:"A wider search may help later, but tonight there is a suitable opening with a concrete deadline. Expanding the list would delay the available application. Finish its missing paragraph first."}],best:"submit",takeaway:"Let the notebook cue an application. Count actions and replies separately.",review:"What target action did you attempt, and did any company respond?",deeper:[{heading:"The familiar recipe, including two pages",paragraphs:["1. Choose a desired outcome and phrase it as already true. 2. Write that affirmation three times in the morning. 3. Repeat it six times around noon. 4. Write it nine times at night. These numbers describe the popular recipe, not a research-backed dose. Practitioner accounts vary in how long they repeat the schedule. [manifest-P01]","5. In the owner’s two-page example, the right page says “I got the job”; the left lists companies she applied to and wants. She reports an offer from a listed company. This is an owner-provided story, not independently verified trial data. Applying survivorship bias here is an inference: the visible success leaves out people who tried the ritual without an offer. The story may be sincere while leaving its cause unresolved. [manifest-T14]"]},{heading:"Keep the rhythm, change what it cues",paragraphs:["The planning evidence concerns a recognizable situation linked to an achievable response. It does not establish that three, six, or nine repetitions influence an employer. Keep the count if it is enjoyable, and put the task beside it: a company, a suitable opening, and today’s action. The left-page list and actual applications provide a practical route toward an offer; this anecdote cannot prove which factor caused hers. [manifest-T02, manifest-T14]","On the right, try “I prepare useful applications.” Add “If the portal fails, I will save the draft and contact recruitment.” Check the deadline, access, and available time. Submit or ask today, then record the exact act. Tomorrow look for the employer’s response without treating silence as a belief problem. Repetitions, preparation, submissions, and offers remain separate entries. This two-page package is ODA’s adaptation, not a tested intervention. [manifest-T02]"]}],sources:["manifest-P01","manifest-T02","manifest-T14"]},{number:7,technique:"Scripting",title:"Scripting: write the work into your future",goal:"Use a future scene to choose and attempt one goal action.",hook:"Your imagined day has the perfect ending. What did you do before breakfast to reach it?",reason:"What will this page help you do before you write another one?",paragraphs:["Scripting is a journal entry written as though a desired future is happening now. Choose a scene, describe its details and feelings, then reread it. Mixed: related best-possible-self writing improved wellbeing and optimism on average; it did not establish that present-tense entries deliver events. Expressive writing studies concern real experiences, not wishes becoming facts.","ODA version: keep the scene, but include the work that led there. Name your specific goal, a current obstacle, and an if-then response. Underline one action you can attempt today. Tomorrow compare the attempted action with your plan, rather than judging whether the whole scene arrived. The combined exercise is an adaptation."],example:{title:"Elena adds the missing work",text:"Elena scripts a calm morning in a new role. She adds the interview preparation that would precede it. After dinner, she records one answer about handling a difficult customer. She hears herself rushing and marks one sentence to shorten. The job is still hypothetical, but there is a real recording to improve tomorrow."},instructions:["Write the future scene, including work and resources it would require.","Underline today’s action; add “If this obstacle appears, then I will…”","Attempt the minimum and review what happened tomorrow."],action:["Record one interview answer","Draft one portfolio caption"],minimum:["Save one answer recording","Save one usable caption"],cue:["After dinner is cleared","When I close my journal"],place:["At my kitchen table","In my portfolio document"],obstacle:"I cannot find a perfect opening sentence",fallback:["Use a rough first sentence","Ask for one specific example"],observation:["The recording I saved","The draft and its remaining gap"],stopRule:"Skip distressing scenes; choose ordinary task notes if future writing feels unhelpful.",scenario:"Elena’s script describes a confident interview. Her interview is tomorrow, and she has no example ready for a common customer-service question.",question:"Which revision makes the page useful tonight?",options:[{key:"draft",text:"Add a real customer example, rehearse one answer, and save a rough recording for tomorrow’s check.",feedback:"This connects the scene to tomorrow’s task. A rough answer can reveal what needs work. It does not secure the job, but it produces preparation she can inspect and improve."},{key:"feelings",text:"Describe the feeling of confidence in more detail before deciding which customer example fits.",feedback:"Exploring feelings can make the scene meaningful. Here the missing element is an answer using real experience. More feeling detail leaves that gap intact; choose an example and rehearse it."},{key:"edit",text:"Polish the entire journal entry so the imagined interview follows a clear and consistent narrative.",feedback:"A coherent story is a writing goal. Elena’s immediate goal is preparing an answer. Editing the narrative uses her limited evening without producing the example she needs for the interview."}],best:"draft",takeaway:"Write a future worth pursuing, then give today one piece of its work.",review:"Which scripted step became an actual attempt, and what remains unfinished?",deeper:[{heading:"How people script",paragraphs:["1. Pick a desired situation, such as a working day in a role you want. 2. Write a journal entry as if that day is already happening. 3. Describe ordinary details: where you are, what you do, and how the scene feels. 4. Read it back and return to it if you want. Some versions add gratitude or a feeling of certainty. These are practitioner instructions, not a validated route to an offer. [manifest-P02]","Keep imagined events labeled as imagined. You can write an ordinary scene without inventing a promise that another person has made. For the ODA exercise, add the necessary work, available resources, and an obstacle you face now. Pick a single task from that page. A typed or spoken entry is an accessibility choice; we do not claim every format has identical research effects. The ritual is optional. [manifest-P02]"]},{heading:"Future writing and real-experience writing differ",paragraphs:["Best possible self research asks people to imagine a good future after working toward it. Carrillo and colleagues found average benefits for wellbeing, optimism, and positive affect, with study-quality limitations. This supports a bounded expectation about reflective writing. It does not establish that present-tense scripting causes the written events to occur. Expressive disclosure has a different target: real experiences or feelings. Its small average benefit does not validate future-event attraction either. [manifest-T08, manifest-T12]","ODA keeps the narrative and adds a practical exit from it. Choose a specific goal already in your course experiment. Name what might block today’s step, then write a response you can afford and perform. Save an opportunity and minimum, attempt it, and review tomorrow. Record an interview rehearsal as preparation, an application as a submission, and a reply only when one arrives. This workflow is a design adaptation, not either writing intervention as originally tested."]}],sources:["manifest-P02","manifest-T08","manifest-T12"]},{number:8,technique:"Vision board",title:"Vision board: give one picture a next step",goal:"Turn one board image into a cue for an achievable action.",hook:"That vision-board desk looks good. What will you do at your own desk today?",reason:"Which image reflects your own priority rather than someone else’s idea of success?",paragraphs:["A vision board gathers images and words representing a desired life. Choose pictures, arrange them, put the board somewhere visible, and revisit it. Mixed: current goals can shape attention, alongside salience and past experience. That does not establish board efficacy or show that pictures attract opportunities. The reticular activating system concerns arousal; calling it a programmable wish filter overstates the evidence.","ODA version: keep an image you care about. Label its specific goal and one action today. Name an obstacle and an if-then response; make seeing the image a start cue. Tomorrow check whether the cue led to your minimum. Noticing an opening and creating it are different claims."],example:{title:"Nora labels the desk",text:"Nora’s board includes a desk in a design studio. She labels it “Build one portfolio sample.” When she sees the picture after breakfast, she opens her unfinished project and writes a caption. The image is less exciting than the studio dream. She saves it anyway and notes that the project still needs feedback."},instructions:["Choose one image; label its specific goal and today’s useful action.","Use seeing it as a cue; plan a response to one likely obstacle.","Attempt the action and check tomorrow whether you noticed the cue."],action:["Write one portfolio caption","Send one project feedback request"],minimum:["Save a usable project caption","Send a focused feedback question"],cue:["When I see the board after breakfast","When I open my project folder"],place:["At my work desk","In my portfolio document"],obstacle:"The picture cues browsing instead of work",fallback:["Open the project before browsing","Use a text reminder beside the file"],observation:["Whether the image cued an actual start","The caption or request I completed"],stopRule:"Use existing pictures or words; skip images that pressure you into spending.",scenario:"Nora sees her board each morning but then browses studio photos. Her portfolio lacks the caption needed to explain one completed project.",question:"What is the most useful change?",options:[{key:"fresh",text:"Replace the studio image with a more inspiring one so the board feels relevant again.",feedback:"A new image may be enjoyable, but the record shows browsing after the cue. It does not show a missing aspiration. Change what seeing the picture asks her to do."},{key:"study",text:"Spend the next morning comparing studio portfolios to understand the standard she hopes to reach.",feedback:"Comparison can inform later work. Nora already has a completed project needing a caption. More browsing would repeat the current pattern unless it answers a specific question needed for that caption."},{key:"label",text:"Label the image “Open project, write caption,” then save one caption before browsing any studio photos.",feedback:"This connects the existing cue to the missing action. Tomorrow Nora can check whether she noticed the label and saved the caption. The board itself does not guarantee a studio job."}],best:"label",takeaway:"Give the picture a task and a cue. Review the task, not the image’s power.",review:"Did seeing your image lead to the saved action, or to something else?",deeper:[{heading:"Build the familiar board without buying anything",paragraphs:["1. Choose a desired direction or situation. 2. Gather a few pictures and words that represent it. 3. Arrange them on paper, an existing board, or a digital page. 4. Place the collection where you intend to revisit it. 5. Look at it and imagine the desired situation. These steps describe the practitioner exercise; they are not evidence that a board brings the situation into existence. [manifest-P03]","For this course, keep one direction instead of adding every possible life improvement. An existing photo, sketch, or written word is enough. Under one image, name the actual task: ask a training question, finish a sample, or submit a suitable application. Choose a place where you can act when the image appears. The materials and layout are your preference, with no scientific requirement to purchase special supplies. Separate arranging pictures from completing the task."]},{heading:"What noticing can and cannot explain",paragraphs:["Attention research describes selection influenced by current goals, physical salience, and selection history. This makes deliberate looking for relevant openings plausible; it does not validate every method proposed to improve noticing. The reticular activating system participates in wakefulness and arousal circuits. Those findings do not establish a board-controlled filter that delivers a job, partner, or house. A newly noticed opening may have existed before you paid attention to it. [manifest-T15, manifest-T19]","ODA turns the image into an explicit reminder rather than assigning it a hidden mechanism. Write the goal, today’s action, and a response to the obstacle most likely to interrupt it. If seeing the board starts another browsing session, plan to open the work file first. Tomorrow check whether the cue occurred, whether you noticed it, and what you actually did. Keep outside responses separate. This image-and-plan bundle has not been tested as a vision-board intervention."]}],sources:["manifest-P03","manifest-T15","manifest-T19"]},{number:9,technique:"Affirmations",title:"Affirmations: choose a line you can use",goal:"Pair an encouraging line with one observable goal action.",hook:"“I am wildly successful” feels false today. Try a sentence that gives you something to do.",reason:"Does this sentence help you attempt the task, or pressure you to feel certain?",paragraphs:["Affirmations are encouraging statements people say or write repeatedly, often phrased as an already-achieved outcome. Choose a line, repeat it, and imagine believing it. Mixed: Wood and colleagues found that one strongly positive statement worsened mood for some low-self-esteem participants. Research self-affirmation often means reflecting on important values, not repeating success slogans; health-behavior findings cannot establish job attraction.","ODA version: keep an encouraging line that feels usable. Name a value and an action expressing it: “I prepare one honest example.” Choose a specific goal, obstacle, and if-then response. Attempt the action today; tomorrow review what you did. Replace or skip a line that makes you feel worse."],example:{title:"Leah changes the sentence",text:"Leah repeats “I am an outstanding speaker” before a meeting and feels more embarrassed. She switches to “I prepare one clear point.” At her desk, she writes a suggestion and practices saying it. During the meeting she uses the first sentence, then loses her place. Her record names the contribution and the unfinished explanation."},instructions:["Choose an encouraging line tied to a value and a specific action.","Name one obstacle; add a feasible if-then response without demanding belief.","Attempt your action today; review the act and how the line felt tomorrow."],action:["Use one prepared meeting sentence","Ask one clear project question"],minimum:["Say the first suggestion sentence","Send one specific project question"],cue:["When the meeting invites suggestions","When I open the project thread"],place:["In our meeting room","In the project message thread"],obstacle:"My encouraging line feels false",fallback:["Use the prepared sentence without an affirmation","Switch to a plain action reminder"],observation:["What I said and the response","Whether the line helped or felt worse"],stopRule:"Replace or skip statements that feel distressing; no forced certainty is required.",scenario:"Leah’s repeated success statement makes her feel worse. She still wants to offer one useful suggestion at a meeting and has a rough sentence ready.",question:"Which adjustment fits both facts?",options:[{key:"persist",text:"Keep the success statement for several more sessions before changing it, while continuing to rehearse the suggestion.",feedback:"Rehearsal may help preparation, but there is no requirement to persist with a statement that worsens her mood. The available suggestion gives her another way to begin without forcing belief."},{key:"action",text:"Use a plain action reminder or skip the affirmation, then offer the prepared sentence when suggestions open.",feedback:"This preserves a feasible contribution while responding to the reported discomfort. Leah can review what she said and how the reminder felt. She does not need certainty about being an outstanding speaker."},{key:"wait",text:"Prepare a stronger statement of personal strengths, and postpone the suggestion until she feels more convinced.",feedback:"Reflecting on values differs from convincing herself of a grand statement. Waiting for conviction makes confidence a condition for an already prepared action. Keep the contribution small and the statement optional."}],best:"action",takeaway:"Use the sentence as an optional cue. Let the action supply evidence.",review:"What did you attempt, and did the sentence help, hinder, or make no difference?",deeper:[{heading:"The popular statement practice",paragraphs:["1. Choose an outcome or personal quality. 2. Phrase it positively, often in the present tense. 3. Say or write it repeatedly. 4. Imagine the desired situation while using the line. 5. Return to the statement at a chosen time. Frequency and wording vary across practitioner versions; the familiar recipe does not establish a scientifically required count or feeling. [manifest-P04]","You may enjoy the practice without making its strongest promise. For ODA, use a sentence that points to work you can actually attempt. “I prepare one clear point” can sit beside your meeting notes. You can also use no sentence at all. An uncomfortable or unbelievable statement is not a test you must pass. Wood and colleagues studied a particular positive statement and short-term mood effects; their result does not show that every kind phrase is harmful. [manifest-T06]"]},{heading:"A value is different from a success slogan",paragraphs:["In self-affirmation research, people often reflect on important values, qualities, or relationships before encountering potentially threatening information. Epton and colleagues pooled health-message experiments and found small average effects on acceptance and intentions, with a behavioral benefit in that setting. Those procedures differ from repeating a desired outcome as already true. They do not establish that a job offer follows from saying “I got the job.” [manifest-T07]","ODA borrows the distinction without claiming the whole ritual is tested. Pick a value, such as honesty, and one way to express it in your existing goal: prepare an accurate example of your work. Save the opportunity and minimum. Write a response to a likely obstacle, such as losing your place, and attempt the sentence today. Tomorrow record the actual contribution and whether the line felt usable. Skip the affirmation if it adds pressure; keep the feasible action. [manifest-T06, manifest-T07]"]}],sources:["manifest-P04","manifest-T06","manifest-T07"]},{number:10,technique:"Visualization",title:"Visualization: rehearse the move inside the scene",goal:"Choose a task, rehearse a difficulty, and make an actual attempt.",hook:"Picture getting the offer. Then practice answering the question that comes before it.",reason:"Will another scene expose a useful gap, or delay an action already ready?",paragraphs:["Visualization means imagining a desired event, often with sensory details and its feeling of success. Settle, picture the scene, participate mentally, and repeat if wanted. Mixed for manifestation: mental simulation supported later behavior on average, but this does not establish event attraction. An early exam study favored process imagery in some comparisons; the later meta-analysis found no reliable subtype winner.","ODA version: keep a brief outcome scene, then rehearse your actual task and one obstacle. Choose a specific goal and an if-then response, attempt one action today, and review tomorrow. Rehearsal remains preparation. Use written steps if imagery does not come; no vivid picture or special feeling is required."],example:{title:"Ben rehearses the difficult question",text:"Ben pictures finishing an interview, then rehearses explaining a gap in his work history. He plans to start with the dates if he freezes. After lunch, he records an answer and notices he has left out what he learned. He adds one sentence. The answer still needs practice, and no interview result exists yet."},instructions:["Keep a brief outcome scene; rehearse the next task and one likely difficulty.","Write a specific goal and an if-then response to that difficulty.","Make the actual attempt today and review it separately from rehearsal tomorrow."],action:["Record an interview practice answer","Send one prepared meeting suggestion"],minimum:["Save one rough answer recording","Send one suggestion sentence"],cue:["After lunch ends","When the meeting invites input"],place:["At my interview practice desk","In the team message thread"],obstacle:"I freeze at the first sentence",fallback:["Start with the dates in my notes","Read the short prepared opening"],observation:["The answer I actually recorded","Preparation and actual contribution, recorded separately"],stopRule:"Stop imagery that increases distress; use ordinary task notes and a daytime opportunity.",scenario:"Ben pictured a successful interview twice. His saved practice answer still avoids explaining the work-history gap. He has five minutes before leaving.",question:"What use of imagery fits the gap?",options:[{key:"rehearse",text:"Rehearse the first gap-explanation sentence, record a rough answer, and check whether it includes the necessary dates.",feedback:"This makes preparation address the observed gap and produces a recording to inspect. Imagery does not secure the interview result. Its useful role here is helping Ben attempt the answer."},{key:"outcome",text:"Repeat the successful-interview scene with richer details, then record how confident it makes him feel.",feedback:"Confidence is a possible observation, but it does not answer the missing question. Ben’s record identifies a specific explanation to practice. Use the remaining time to rehearse and record that explanation."},{key:"research",text:"Use the time to compare several visualization methods before choosing which one to practice tonight.",feedback:"Method comparison may be interesting, but no evidence here requires one subtype before beginning. Ben already knows the missing task. A short attempt supplies more relevant information than another method search."}],best:"rehearse",takeaway:"Let the scene reveal a task. Rehearsal prepares; an attempt tests.",review:"What did you actually attempt after rehearsal, and what gap became visible?",deeper:[{heading:"The familiar outcome scene",paragraphs:["1. Choose an event you would like to happen. 2. Settle somewhere comfortable. 3. Picture a short scene showing the desired result. 4. Imagine participating, with details you find meaningful. 5. Return to the scene if you want. Some practitioner versions ask for strong emotion or a feeling of already having the result. These instructions document a ritual; they do not establish that its scene attracts an external event. [manifest-P05]","For ODA, keep the outcome scene short enough to leave time for work. Identify the next task that belongs between now and that scene. Mentally rehearse a difficulty in that task, then write the response you will try. A person who does not form vivid pictures can describe the steps instead. That is an accessibility option, not proof that every preparation format has the same effect. No imagined employer reply should be logged as a real one."]},{heading:"Why there is no universal imagery winner",paragraphs:["The early Pham and Taylor exam study compared studying-process imagery, desired-grade imagery, combinations, and a control. Some comparisons favored process imagery; the grade finding does not justify a reliable process-versus-control benefit. Cole and colleagues later pooled varied mental simulations and found an average behavior benefit, without establishing differences between subtypes. Several subgroups were small. It would overstate this evidence to promise that one scene always works best. [manifest-T17, manifest-T04]","ODA asks what preparation your own task needs. If you know the goal but avoid its first sentence, rehearse starting and handling that obstacle. Save a feasible minimum, cue, place, and response. Try the action today, then review tomorrow. Record both a useful rehearsal and any actual task separately. If preparation continues without an attempt, shorten it or choose another available opening. This particular scene-to-attempt sequence is an ODA adaptation, not a protocol validated by the meta-analysis."]}],sources:["manifest-P05","manifest-T04","manifest-T17"]},{number:11,technique:"55x5 method",title:"55x5: keep time for the actual task",goal:"Pair optional writing with one feasible action and a review.",hook:"Fifty-five lines written, application still blank? Put the next useful sentence where you can act on it.",reason:"How much writing time can you spare without losing the useful task?",paragraphs:["The 55x5 method writes one present-tense affirmation 55 times a day for five days. Pick a desired outcome, repeat the same sentence, and complete the daily count. Not supported: that count or five-day run attracting an outcome. Some idealized-fantasy experiments reduced immediate energy; that does not show all imagination or this writing ritual harms effort.","ODA version: keep writing if you enjoy it, with repetitions optional. Choose a specific goal and one achievable action each day. Name the obstacle, then attach an if-then response to a recognizable cue. Act today before adding more writing; tomorrow review the task. Research supports specific planning, not the special repetition schedule."],example:{title:"Sam protects the application time",text:"Sam likes copying “I prepare useful applications,” but finishing 55 lines uses his entire break. He keeps a few lines and reserves five minutes after lunch for the application. If he lacks a detail, he writes a question for recruitment. Today he sends the question. He records that request, not an application or offer."},instructions:["Choose one goal; reserve time for action before deciding how much to repeat.","Add a recognizable cue and an if-then response to one obstacle.","Attempt today’s task and review it tomorrow; repetitions remain optional."],action:["Send a missing-detail question","Complete one application section"],minimum:["Send one recruitment question","Save one complete section"],cue:["After lunch ends","After my optional writing session"],place:["In the recruitment email draft","At my application desk"],obstacle:"Repetitions use all my available time",fallback:["Skip repetitions and do the minimum","Reserve action time before opening the notebook"],observation:["Actual task and writing time separately","What I sent or saved"],stopRule:"Reduce or skip writing that causes strain or crowds out your available action time.",scenario:"Sam completed two days of 55 repetitions. Neither day left time for his application. He has the same short break available today.",question:"What change tests a more useful routine?",options:[{key:"faster",text:"Write the repetitions faster so he can preserve the full ritual and possibly start the application afterward.",feedback:"Writing faster may still leave the application without an opening. His record identifies the time conflict. Reserve a feasible task slot first, then choose how much optional writing fits around it."},{key:"weekend",text:"Finish all five writing days, then give the application a longer session at the weekend.",feedback:"A weekend session might be possible, but it postpones the task to protect an unsupported count. There is already a small opportunity today. Test that opening before adding more repetition."},{key:"reserve",text:"Reserve five minutes for one application section, shorten or skip repetitions, and review the saved section tomorrow.",feedback:"This changes the condition that blocked the task. It preserves writing as a preference while making the application attempt feasible. A saved section remains preparation for submission, not an offer."}],best:"reserve",takeaway:"Protect the action opening. A completed count is not a completed goal task.",review:"What task did you attempt, and how much time did the writing leave for it?",deeper:[{heading:"The familiar five-day repetition recipe",paragraphs:["1. Choose one desired outcome. 2. Write a positive sentence as though it has already happened. 3. Copy the sentence 55 times in a daily session. 4. Repeat that session for five days. 5. Return attention to the desired result while writing. The recipe’s exact count is a practitioner requirement, not a dose established by controlled research. Versions may add instructions about emotion or uninterrupted focus. [manifest-P06]","Keep the recognizable writing format if it is enjoyable, but make its cost visible. Before starting, decide what time today’s actual goal action needs. A shorter writing session or no repetitions is allowed in the ODA version. Missing a day does not mean a future result has been canceled. A finished page belongs in the record as writing; a saved application section belongs as task work. Neither entry says an employer has made an offer."]},{heading:"Repetition is not the planning ingredient",paragraphs:["Gollwitzer and Sheeran’s meta-analysis supports linking a specific situation to a goal-directed response across varied tasks. It does not test 55 repetitions or a five-day manifestation rule. Kappes and Oettingen found that some idealized positive fantasies reduced immediate energy. Their short experiments are a caution about pleasant imagined completion replacing preparation, not proof that every optimistic thought or repeated sentence is harmful. [manifest-T02, manifest-T05]","ODA uses the page to hold a practical plan. Name your goal, the task’s smallest useful unit, and the opening in which you can do it. If writing tends to fill the whole break, plan to do the action first. If a missing detail blocks a section, send the specific question. Attempt today, then review tomorrow: did the cue arrive, what task was done, and what remains? The writing-plus-action schedule is an adaptation, without a promised five-day outcome."]}],sources:["manifest-P06","manifest-T02","manifest-T05"]},{number:12,technique:"Two-cup method",title:"Two cups: name the bridge between them",goal:"Use the labels to choose a feasible action and obstacle response.",hook:"Pouring water is the easy part. What bridges your current situation and the label you want?",reason:"What would make the desired label feasible with your time and resources?",paragraphs:["The two-cup method labels one cup with a current situation and another with a desired one. Fill the first, imagine the change, pour into the second, and drink the water. Not supported: water carrying intention or shifting dimensions. Goal-setting evidence concerns specific goals, strategies, and feedback, not a quantum explanation for pouring.","ODA version: keep the cups as symbols, or use two drawn circles. Between the labels, write a specific goal, a real obstacle, and an if-then plan. WOOP names wish, outcome, obstacle, and plan; research supports that planning combination on average. Attempt one bridge action today. Tomorrow review what you did, separately from any outside result."],example:{title:"Omar writes the bridge",text:"Omar labels cups “Portfolio unfinished” and “Ready to apply.” Between them he puts a note: “Save one project caption after lunch.” If he cannot explain the project, he will describe its main decision. He pours the water, then writes the caption. The portfolio still needs another project; the note records exactly what changed."},instructions:["Label the current situation and a desired goal; keep the change feasible.","Between them, write today’s bridge action and an obstacle-response if-then plan.","Attempt the bridge action; review the actual work tomorrow."],action:["Write one project caption","Ask about one training requirement"],minimum:["Save a caption describing one decision","Send one training question"],cue:["After lunch ends","When I put away the cups"],place:["In my portfolio document","At my kitchen table"],obstacle:"The desired label requires more resources",fallback:["Ask about access or a smaller route","Describe one project decision in plain words"],observation:["The bridge action I actually completed","What remains between the two labels"],stopRule:"Use drawings if preferred; drink only safe water if you choose the drinking step.",scenario:"Omar’s desired cup says “Ready to apply.” His portfolio has one finished project without a caption, and a second project still incomplete.",question:"What bridge action fits a five-minute opening?",options:[{key:"caption",text:"Write and save the finished project’s caption, then record what still prevents the portfolio from being ready.",feedback:"This chooses a feasible unit and preserves the remaining gap. A caption does not make the whole portfolio ready, but it gives the next review a real piece of progress to examine."},{key:"rename",text:"Change the desired label to “Hired designer” to keep the overall ambition visible during the ritual.",feedback:"The larger ambition can matter, but changing the label does not address the unfinished portfolio. Keep the aspiration and choose the small task that the available five minutes can support."},{key:"schedule",text:"Map every remaining portfolio task before touching the caption, so the whole route is fully planned.",feedback:"A task map may help a later review. In this short opening, the missing caption is already known. Completing it tests a feasible bridge instead of spending the whole opportunity preparing more."}],best:"caption",takeaway:"Let the labels name the gap. Let an affordable action bridge part of it.",review:"What changed through your action, and what still stands between your two labels?",deeper:[{heading:"The recognizable two-cup ritual",paragraphs:["1. Take two cups and label the first with the situation you have now. 2. Label the second with the situation you want. 3. Put water in the first cup. 4. Imagine the desired change as you pour into the second. 5. Drink the water and return attention to the desired situation. Some practitioner descriptions call this dimension jumping. That metaphysical explanation is not established by the inspected evidence. [manifest-P07]","You can keep the symbolic transfer without taking its explanation as fact. Existing cups or two drawn circles are enough for ODA’s exercise. Write an action between the labels before pouring. Avoid labeling an uncertain decision by someone else as already secured. A usable portfolio caption is your action; being hired is an outcome involving an employer. If you drink, use only water that is safe to drink. No special vessel or purchase is needed."]},{heading:"Use the gap for WOOP and feasibility",paragraphs:["WOOP organizes a wish, its desired outcome, a current obstacle, and a plan. The mental-contrasting-with-implementation-intentions meta-analysis found a modest average benefit for goal attainment, with variation and publication-bias indications. It did not test cups or water. Goal-setting theory also makes commitment, feedback, ability, and task complexity relevant. A meaningful label needs a workable route; a hard goal without access or a strategy is not enough. [manifest-T01, manifest-T11]","ODA makes the bridge explicit. Choose one specific task for your existing goal. Name an obstacle you can respond to, and check external barriers such as missing equipment or money. “If I cannot access the tool, I will ask about an available alternative” can make a support request the action. Save the minimum and cue, attempt today, then review tomorrow. Record requests separately from help received. The symbolic cups plus this practical workflow are an adaptation, not a tested combined treatment."]}],sources:["manifest-P07","manifest-T01","manifest-T11"]},{number:15,technique:"Gratitude journaling",title:"Gratitude: keep appreciation honest",goal:"Record something you actually appreciate and attempt one useful action without denying a difficulty.",hook:"You can appreciate a friend’s help and still admit the application was rejected.",reason:"What deserves appreciation without making you hide what needs to change?",paragraphs:["Gratitude journaling records things you appreciate, often with reasons and a reread. Some manifestation versions thank life for a future event as if it happened. Mixed: gratitude interventions show small average wellbeing benefits against some controls, with little advantage over psychologically active alternatives. Symptom findings are modest; gratitude is not sufficient treatment or evidence of future-event attraction.","ODA version: keep the journal and describe something real. Name your specific goal and a difficulty alongside the appreciation. Add an if-then response and one action today, such as thanking a helper or requesting focused feedback. Tomorrow review the action and any response. A grateful entry does not require hiding disappointment."],example:{title:"Aisha keeps both facts",text:"Aisha writes that she appreciates a friend checking her application. She also records the rejection email. After breakfast, she asks the friend which opening sentence needs work. Her plan allows a short message if a call is unavailable. The friend cannot reply today. Aisha logs the question and the disappointment without inventing feedback."},instructions:["Write one real appreciation and its reason; keep any difficulty visible.","Name today’s useful action and an if-then response to one likely obstacle.","Attempt the action; review it and any response tomorrow."],action:["Send a focused feedback request","Thank someone for specific help"],minimum:["Send one application feedback question","Send one specific thank-you message"],cue:["After breakfast ends","When I finish the gratitude entry"],place:["In my message thread","At my kitchen table"],obstacle:"My helper is unavailable for a call",fallback:["Send one concise feedback question","Choose another available reviewer"],observation:["Request sent and any actual reply","Appreciation and difficulty, recorded honestly"],stopRule:"Skip forced gratitude; persistent distress deserves support beyond a journal.",scenario:"Aisha appreciates a friend’s support but is upset by an application rejection. Her friend has offered to answer one focused question by message.",question:"What entry and action fit the situation?",options:[{key:"positive",text:"List only the supportive moments today and postpone examining the rejection until she feels more grateful.",feedback:"Appreciation can remain part of the entry, but it does not require postponing a concrete problem. The offered feedback opening lets Aisha ask one useful question while acknowledging that rejection hurts."},{key:"both",text:"Record the support and disappointment, then ask which opening sentence would make the next application clearer.",feedback:"This keeps gratitude grounded in an actual event and uses the available support. The message is a request, not feedback received. Tomorrow Aisha can record any reply and choose a revision."},{key:"future",text:"Write thanks for the next offer as if it happened, then reread the entry before requesting feedback.",feedback:"That future-focused version is a practitioner ritual, not the gratitude intervention tested in the cited reviews. It cannot establish an offer. A real appreciation and focused question keep the entry connected to facts."}],best:"both",takeaway:"Appreciate what is real. Keep the difficulty and the next useful action visible.",review:"What did you appreciate, what action did you attempt, and did anyone respond?",deeper:[{heading:"The familiar gratitude journal",paragraphs:["1. Open a notebook or your usual writing tool. 2. Name something you appreciate. 3. Describe why it matters to you. 4. Add another item if you want. 5. Reread the entry at a chosen time. A first-hand practitioner account describes this reasons-and-rereading format. Manifestation variants may add thanks for a wished-for future event; that is a different claim from appreciating help already received. [manifest-P10]","For ODA, an ordinary detail is enough: a useful answer, a shared tool, or a moment of rest. You do not need a positive item for every problem. If a rejection, access barrier, or disappointment matters today, record it alongside the appreciation. Choose one useful action that fits your existing goal. The entry is reflection; thanking someone or sending a request is a separate act. Neither writing nor a request guarantees a response."]},{heading:"Small average benefits, with comparison limits",paragraphs:["Davis and colleagues found small average wellbeing benefits for gratitude interventions against some controls. Gratitude did not outperform psychologically active alternatives for wellbeing, and anxiety findings were inconclusive. Cregg and Cheavens found modest average pooled depression-and-anxiety symptom changes, with larger effects against waitlist than active controls; their separate anxiety analysis was inconclusive. Those findings do not establish one optimal journal dose, guaranteed relief, or gratitude as sufficient treatment. They also do not test future events arriving because someone thanked the universe. [manifest-T09, manifest-T10]","ODA adds a practical plan without calling it the tested intervention. Keep your goal specific, name the current obstacle, and choose an if-then response. If a helpful person cannot call, send one focused question instead. Attempt today and review tomorrow. Note the request separately from any answer, and let disappointment remain part of the record. You can skip gratitude if it feels forced and still make the useful move or seek support."]}],sources:["manifest-P10","manifest-T09","manifest-T10"]},{number:16,technique:"Act as if / embodiment",title:"Act as if: practice without spending ahead",goal:"Give a desired identity one affordable behavior.",hook:"You want to feel like a professional. Start with a work sample before buying the wardrobe.",reason:"Which behavior expresses your goal without spending money you need elsewhere?",paragraphs:["Act as if, also called embodiment, behaves like the person who already has a desired outcome. Choose that identity, imagine its routines, then adopt some behavior or symbol. Mixed: specific goals and feedback can support performance; pretending the outcome is secured has no established attraction mechanism. Manifestation-belief surveys found associations with some financial risks, not proof that belief caused them.","ODA version: keep the identity rehearsal and choose an affordable behavior under your control. Name the specific goal, obstacle, and if-then response. A professional might prepare a useful sample or ask a clear question. Do one action today and review it tomorrow. Buying symbols is optional; another person’s agreement remains theirs."],example:{title:"Rafi practices the role",text:"Rafi wants to work as a freelance analyst. He considers buying an expensive office chair, then chooses to improve a sample spreadsheet instead. After lunch, he checks one calculation and adds an explanation. If software access fails, he will use a free available tool. The sample is clearer; he still has no client."},instructions:["Name the desired identity and one specific, affordable behavior it could express.","Add an obstacle-response if-then plan; keep other people’s decisions outside your promise.","Attempt that behavior today; review what you did and spent tomorrow."],action:["Improve one work sample","Ask one focused client question"],minimum:["Save one explained sample calculation","Send one project clarification question"],cue:["After lunch ends","When I open the sample file"],place:["At my work desk","In my sample spreadsheet"],obstacle:"I lack access to the planned tool",fallback:["Use an available free tool","Write the explanation in a text file"],observation:["Work produced and money actually spent","The change I saved in the sample"],stopRule:"Keep spending within your means; do not treat uncertain income or consent as secured.",scenario:"Rafi wants freelance work and has no confirmed client. Buying a premium tool would use money reserved for essentials; an available free tool supports his sample.",question:"Which act best expresses the role today?",options:[{key:"sample",text:"Improve one sample with the available tool, record the change, and keep essential spending protected.",feedback:"This gives the identity an affordable behavior and an inspectable result. It does not secure a client, but it strengthens something Rafi can share. Essential money need not fund an uncertain symbol."},{key:"purchase",text:"Buy the premium tool now so his work environment matches the professional identity he wants to inhabit.",feedback:"A tool can be useful when a task requires it and the cost fits. Here a free tool covers the task, while the purchase threatens essentials. Identity rehearsal does not establish future income."},{key:"wait",text:"Wait for a confirmed client before making a sample, so he avoids investing effort in an uncertain outcome.",feedback:"Protecting money is sensible, but a small sample can be made with available resources. Waiting for certainty also blocks this affordable test. Set a feasible effort limit and inspect what the sample needs."}],best:"sample",takeaway:"Practice the behavior you can afford. Keep identity, spending, and outside outcomes separate.",review:"What behavior did you attempt, what did it cost, and what result is actually known?",deeper:[{heading:"The familiar identity rehearsal",paragraphs:["1. Choose the situation or identity you want. 2. Imagine how that person spends an ordinary day. 3. Pick behaviors, objects, or routines associated with that life. 4. Act as if the desired change has already occurred. 5. Notice how the rehearsal feels and return to it if wanted. A practitioner account describes preparing clothes and luggage as though a job were confirmed. Its later offer is an anecdote, not a controlled comparison. [manifest-P11]","ODA keeps the role rehearsal but asks for a behavior with a safe cost. Preparing a work sample, arriving with an agenda, or asking a clear question can fit an existing goal. Expensive possessions are not a condition for practicing the role. Do not act as though another person has consented or an unconfirmed employer has hired you. A possible future is a direction, not a resource already in hand."]},{heading:"Goals need feedback and real resources",paragraphs:["Goal-setting theory describes how specific, challenging goals can support performance when commitment, feedback, ability, and task complexity are considered. It does not establish that adopting an identity independently produces the desired outcome. Dixon and colleagues found that manifestation beliefs correlated with some self-reported financial risks and bankruptcy, without establishing causation. Confidence or perceived success is not the same as income already received. [manifest-T11, manifest-T13]","ODA chooses one behavior before a symbol. Name the concrete result of today’s task and the available time or tools. Plan a response to a likely obstacle, such as missing software access, and keep the minimum affordable. Attempt it today and review tomorrow. Record the work produced, any cost, and any outside response separately. If a purchase or promise assumes success has already arrived, reconsider the route. This identity-to-action package is an adaptation; the cited studies did not test it as an embodiment intervention."]}],sources:["manifest-P11","manifest-T11","manifest-T13"]},{number:17,technique:"Letter from your future self",title:"Future-self letter: include the difficult Tuesday",goal:"Give your future-self letter one feasible action for this week.",hook:"Your future self has a calmer life. How did they handle a difficult Tuesday?",reason:"Which future matters to you enough to make one affordable move this week?",paragraphs:["A future-self letter imagines a later you writing to the person you are now. Choose a future date, describe the life and changes, offer encouragement, then reread. Mixed: related best-possible-self research supports average wellbeing and optimism benefits, not communication from the future or guaranteed goal attainment. That research includes working toward the imagined life.","ODA version: keep the letter’s voice, but include effort, help, and a difficult ordinary day. Name your specific goal, current obstacle, and an if-then response. Choose one action today and save a feasible opportunity. Specific planning has research support; this letter-plus-plan package is an adaptation. Tomorrow review your attempt, not whether the future prediction came true."],example:{title:"Jess writes the ordinary day",text:"Jess’s future letter describes a steadier work week, then explains asking for priorities when tasks clash. Today, after opening her work inbox, she sends one clarification question. If her manager is unavailable, she will use the team thread. The answer does not arrive immediately. Her record shows a request and a still-unresolved workload."},instructions:["Write from your future self; include effort, help, and an ordinary obstacle.","Choose today’s action and a specific cue; add a feasible if-then response.","Attempt the minimum and review the actual record tomorrow."],action:["Send one work-priority question","Reserve a feasible practice opening"],minimum:["Send one clarification request","Confirm one available practice slot"],cue:["When I open my work inbox","After dinner is cleared"],place:["In the team message thread","At my kitchen table"],obstacle:"The person I need is unavailable",fallback:["Use the agreed team message route","Choose another available practice opening"],observation:["Request sent and any actual answer","The opening I actually confirmed"],stopRule:"Use a nearer or less demanding future if the letter adds pressure; pausing is allowed.",scenario:"Jess’s future letter promises a balanced work week. Today two urgent tasks clash, and her manager invited clarification questions in the team thread.",question:"Which addition earns its place in the letter?",options:[{key:"calendar",text:"Describe a complete ideal-week calendar before asking which of today’s urgent tasks should come first.",feedback:"A calendar can guide later choices, but it cannot decide this priority conflict by itself. Jess has an available clarification route. Use that opening and keep the unanswered question visible."},{key:"certainty",text:"Add stronger encouragement about trusting the future, then wait until the workload feels less overwhelming.",feedback:"Encouragement may be welcome, but waiting for a different feeling leaves both urgent tasks competing. A short clarification request is already feasible. The letter should help her take that step without predicting the reply."},{key:"request",text:"Describe asking for priorities on difficult days, then send one clarification question through the agreed team thread.",feedback:"This gives the future scene a behavior that fits the current obstacle. Sending is her action; an answer remains unknown until it arrives. Tomorrow she can review the request and choose the next step."}],best:"request",takeaway:"Let the future voice name today’s work and the support it may need.",review:"Which letter step became an attempt, and what help or result remains unknown?",deeper:[{heading:"The familiar letter format",paragraphs:["1. Pick a future point in your life. 2. Imagine being yourself at that point. 3. Address a letter to your present self. 4. Describe what changed and how ordinary life feels. 5. Offer encouragement or advice, then reread the letter. A practitioner resource documents this future-to-present voice and its compassionate framing. Dates and greetings are format choices, not scientifically necessary ingredients. [manifest-P12]","For ODA, write about a future you want without claiming it is a message or prediction. Include an ordinary difficulty, the effort involved, and help you might need. A calmer work week may require a priority conversation rather than stronger certainty. Keep the direction linked to your course experiment. Underline one feasible action for the person who will wake up tomorrow with the same real resources. A near-future letter is allowed if a distant one feels burdensome."]},{heading:"Hopeful writing needs a way back to today",paragraphs:["The best possible self meta-analysis found average benefits for wellbeing, optimism, and positive affect compared with controls. Samples were often young students, and no study met every quality criterion. The imagined future follows working toward it; the findings do not establish that letters predict or deliver external events. Implementation-intention research separately supports a specific cue linked to an achievable response. Neither source tested this exact future-letter package. [manifest-T08, manifest-T02]","ODA uses the letter to choose a move. Name a specific goal, identify the obstacle closest to today’s task, and write “If that happens, I will…” with a feasible response. Save the cue, place, and minimum, then attempt it today or at the chosen later opening. Tomorrow review what actually occurred: a request, a task, a delay, or a pause. If another person has not replied, leave the answer unknown. Revise the next step without pretending the imagined future is already evidence."]}],sources:["manifest-P12","manifest-T08","manifest-T02"]}],a=[...l,...c].sort((e,o)=>e.number-o.number).map(s),p=[...n,...i,{id:"M01",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 independent effects from 21 articles, 15,907 participants: modest average goal-attainment benefit, g = .336 [.229, .443]. Bias adjustment estimated .242 [.143, .342].",limitation:"Substantial variation and publication-bias indications. This course and its brief exercises were not tested; outcomes are not guaranteed."},{id:"M02",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 independent tests, 8,461 participants: specific if-then planning supported goal attainment on average, d = .65 [.60, .70].",limitation:"Older heterogeneous evidence, not uniformly preregistered. Plans do not eliminate effort, memory, practical constraints, or uncertainty."},{id:"M03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 experiments, 19,951 participants overall. Goal-attainment analysis used 18,398 participants: d = .40 [.32, .48]; a small-study sensitivity adjustment estimated .19 [.10, .28].",limitation:"Goals and interventions varied. Moderator associations do not require public reporting. No validation of this exact log, review schedule, or ODA course."},{id:"M04",title:"Cole et al. · 2021 · Mental simulation and behavior change",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 studies, 123 effects, 5,685 participants: overall mental-simulation effect g = .49 [.37, .62]. The omnibus subtype comparison was nonsignificant.",limitation:"Mostly student samples and varied simulations. Process-only imagery had five effects with an inconclusive estimate. No reliable subtype ranking or validation of this brief exercise."},{id:"M07",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Belief in manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Three US online survey samples, 1,023 participants: manifestation belief correlated with some financial-risk reports and reported bankruptcy, but not reported income or education.",limitation:"Associations do not establish causation or objectively test every manifestation technique. Self-reported financial outcomes are not an individual forecast."},{id:"M10",title:"Gollwitzer & Brandstätter · 1997 · Specific opportunity planning",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"Study 2 assigned 86 students a report. Among 36 identifiable returners, 12/17 planners versus 6/19 controls wrote within two days.",limitation:"The 71% versus 32% comparison concerns returners, not everyone recruited. Planning did not increase overall cooperation. Narrow student task; no ODA-course validation."},{id:"M11",title:"Oettingen et al. · 2015 · Planning and calendar scheduling",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Study 1 analyzed 84 undergraduates. The planned contrast favored mental contrasting plus if-then plans for scheduled hours, p = .03; omnibus p = .057.",limitation:"Scheduling was measured, not completed work or productivity. Incomplete respondents were excluded; the brief course adaptation and external-feasibility taxonomy were not tested."},{id:"M14",title:"NIMH · Help for mental illnesses",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Official guidance provides qualified-care and crisis routes for distress, impairment, or immediate danger.",limitation:"Guidance, not an efficacy study. ODA does not diagnose or treat mental illness; outside the US use local care and emergency services."},{id:"manifest-positive-fantasies",title:"Kappes & Oettingen · 2011 · Idealized positive fantasies",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Four primarily student experiments found lower immediate energy after some idealized positive fantasies. Study 3 compared positive with neutral or undirected fantasies, not questioning fantasies.",limitation:"Small short experiments. Not all optimism or imagination is harmful; a recurring fantasy loop and a brain signal of completed goals were not measured."},{id:"manifest-belief-study",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Belief in manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Three US online surveys totaling 1,023 participants linked manifestation belief with confidence and some financial-risk reports, including reported bankruptcy. No association with reported income or education.",limitation:"Associations do not establish causation or objectively test every technique. Self-reported outcomes are not an individual forecast."},{id:"manifest-murphy",title:"Joseph Murphy · The Power of Your Subconscious Mind · Publisher provenance",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"The publisher identifies Murphy's popular self-help book and its imagination and belief teachings.",limitation:"Publisher synopsis, not a controlled study. Exact bedtime ritual passages were not verified. No evidence here for wealth attraction, healing, or uniquely effective bedtime learning."}],t=[{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"en",title:"Dream still waiting? Make one useful thing",goal:"Produce one usable piece of work for a goal you choose.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Another week of wanting a different life? Give one wish a piece of work.",reason:{id:"manifest-1-reason",label:"Whose goal is this, and what deserves your time?",kind:"text",maxLength:160,optional:!0,suggestions:["My goal; evening scrolling can wait","Family priority; extra polishing can wait","Someone else’s goal; reconsider the time","I am unsure whose goal this is"]},why:{id:"manifest-1-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A better job is an outcome. Improving one résumé line is a behavior. Other people still decide whether to call. Choose work worth doing without making their reply the test of your effort.","In one student experiment, selecting a starting time and place improved timeliness among people who returned a report. It did not increase overall cooperation. A plan can support starting; it cannot guarantee results. Choose one usable line, answer, or request today. Keep this goal through the course, and bring back what actually happened."],example:{title:"Daniel makes a start",text:"At the kitchen table after dinner, Daniel gives his logistics-job goal ten minutes. He rewrites one résumé line to describe scheduling eight warehouse shifts. The wording still feels clumsy. He saves it anyway and records the change. No employer has seen it yet. Tomorrow he can improve a real draft."}},move:{invitation:"Name your own useful act; suggestions show Daniel’s résumé example.",instructions:["Name the document, question, or object you will change before saving.","Do the minimum; record it separately from any outside reply."],prompts:[],suggestions:{action:["Rewrite a résumé line about scheduling shifts","Ask a reviewer which résumé detail is missing","Build a work sample showing shift coverage"],minimum:["Save one résumé sentence about scheduling shifts","Send the résumé-detail question","Save a work sample showing shift coverage"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After dinner is cleared","When lunch ends","After my morning drink"],place:["At my kitchen table","At the library desk","In the résumé document"],minutes:[10,2,5],fallback:["Write one shift change in plain words","Choose and name another available opening","Ask library staff about computer access"],observation:["The résumé sentence I actually saved","Whether I sent the résumé question","What prevented the minimum"]},suggested:{action:"Rewrite a résumé line about scheduling shifts",minimum:"Save one résumé sentence about scheduling shifts",minutes:10,cueHint:"After dinner is cleared",placeHint:"At my kitchen table",obstacleHint:"My available time is shorter than planned",fallbackHint:"Write one shift change in plain words",observationHint:"The résumé sentence I actually saved"},accessibleAlternative:"Type, dictate, or use your usual tools; ask for practical assistance if needed.",stopRule:"Pause unsafe or unaffordable steps; choose practical support instead."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Daniel has a suitable vacancy and ten minutes before dinner. His résumé does not describe the scheduling work it requires.",question:"What is the strongest first test?",options:[{id:"manifest-1-research-more",text:"Compare more vacancies to check whether this role really matches the kind of life he wants.",feedback:"Comparing roles can clarify a goal. This vacancy already fits, and the missing piece is a usable description of Daniel's experience. Improve that line in the available time."},{id:"manifest-1-improve-line",text:"Rewrite one résumé line for this vacancy, save the draft, and note what still needs work.",feedback:"This produces something Daniel can use while staying within ten minutes. The draft may need feedback and the employer may not respond. Neither fact erases the actual work."},{id:"manifest-1-clarify-future",text:"Write a detailed description of his ideal working day before deciding what to put on the résumé.",feedback:"A desired working day may guide later choices. Daniel already chose a suitable role. More description postpones this concrete gap. Write the résumé line, then review what it needs."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"Give the wish a useful act. Record the act separately from the answer you hope for.",followUp:{questionId:"manifest-1-return",question:"What usable work exists after your saved attempt?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"What a starting plan can support",paragraphs:["Gollwitzer and Brandstätter's 1997 Study 2 assigned 86 Munich students a report about Christmas. Planners chose an exact time and place, pictured that opportunity, committed to starting, and recorded those choices. Among the 36 identifiable report returners, 12 of 17 planners and six of 19 controls wrote within the requested two days. Those percentages describe returners, not everyone recruited. Planning did not increase overall cooperation. [M10]","The lesson borrows the concrete opportunity, then asks for usable work at that opportunity. That general-purpose adaptation was not tested in the Christmas-report study. A date alone does not tell you where the time will come from. Use an event you can recognize and a place you can access. If the resources are missing, asking for them can be the actual move. Record that request as a request, even when help has not arrived."]},{heading:"A wish does not control other people",paragraphs:["Wang and colleagues' 2021 review pooled 24 independent effects from 21 articles, with 15,907 participants. Pairing a desired outcome with an obstacle and an if-then response showed a modest average goal-attainment benefit: g = .336, with a 95% confidence interval from .229 to .443. Findings varied substantially, and a publication-bias adjustment reduced the estimate. This supports bounded planning, not a promise for this course. [M01]","Dixon and colleagues studied manifestation beliefs in three US online surveys totaling 1,023 participants. Belief correlated with some financial-risk reports and reported bankruptcy, but not reported income or education. These associations do not show that belief caused bankruptcy or objectively test every manifestation exercise. [M07] Use your wish to choose work and assess constraints. Do not infer that thoughts attracted an opportunity, caused hardship, or made you deserve an outcome. Money, care, access, and other people's decisions still matter."]}],sourceIds:["M10","M01","M07"]}},{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"en",title:"Rehearsing again? Give the scene an ending",goal:"Rehearse one sticking point, then produce the next usable part of your existing goal task.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"The finished life is easy to picture. What happens when you meet the blank page?",reason:{id:"manifest-2-reason",label:"Will another rehearsal help, or replace the actual attempt?",kind:"text",maxLength:160,optional:!0,suggestions:["It exposes a missing instruction","It delays a ready sentence","I have no rehearsal record yet"]},why:{id:"manifest-2-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Retrieve your chosen task and any record. Rehearsing means mentally doing a particular move, such as saying the first sentence. Listing steps is a different kind of preparation. Neither is the real attempt.","A review found average behavior benefits from mental simulation, but did not establish a best subtype. It does not prove that this brief rehearsal works. Use it only to identify your sticking point and a response. Describe the move in words if pictures do not come. Then make the next usable line in the same task."],example:{title:"Daniel meets the blank line",text:"Daniel returns to his résumé after dinner. For thirty seconds he rehearses describing a difficult scheduling change. He expects to freeze, so he practices starting with “Changed eight shifts when…” Then he types a usable sentence. He deletes two words and leaves a question for feedback. The rehearsal missed how much detail he needed."},rehearsal:{label:"Optional preparation",steps:["Describe the next move and one likely sticking point.","Rehearse your first response once. This is preparation."]}},move:{invitation:"Keep your named task; the résumé suggestions are editable examples.",instructions:["Keep the saved action, minimum, cue, and place; target its sticking point.","Without a plan, name your act and available opening before saving.","Rehearse once, then act; rehearsal alone is preparation."],prompts:[],suggestions:{action:["Rehearse, then write one résumé scheduling sentence","Rehearse, then ask about a résumé detail","Use written steps to revise a résumé date"],minimum:["Save one résumé sentence after rehearsal","Send the résumé-detail question","Save one corrected résumé date"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After dinner is cleared","When lunch ends","When the résumé document opens"],place:["At my kitchen table","At the library desk","In the résumé document"],minutes:[5,2,10],fallback:["Stop rehearsing; write one actual shift change","Skip imagery; use the written first step","Ask the reviewer which detail is missing"],observation:["What rehearsal missed in the real act","The résumé sentence I actually produced","Whether I only rehearsed"]},suggested:{action:"Rehearse, then write one résumé scheduling sentence",minimum:"Save one résumé sentence after rehearsal",minutes:5,cueHint:"After dinner is cleared",placeHint:"At my kitchen table",obstacleHint:"I keep refining the rehearsal instead of beginning",fallbackHint:"Stop rehearsing; write one actual shift change",observationHint:"What rehearsal missed in the real act"},accessibleAlternative:"Type, dictate, or use your usual tools; ask for practical assistance if needed.",stopRule:"If planning in bed keeps you awake, stop and use a daytime opportunity."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Daniel can describe his first résumé sentence and has the document ready. He is tempted to rehearse the whole application again.",question:"Which next move serves this attempt?",options:[{id:"manifest-2-full-rehearsal",text:"Rehearse the entire application once more so he can choose the strongest opening before writing anything.",feedback:"A full rehearsal may prepare later work. Daniel already has a usable opening and a ready document. Another complete run delays the available test. Type the sentence and inspect it."},{id:"manifest-2-new-goal-scene",text:"Picture his first day in the new role to renew motivation before returning to the application later.",feedback:"Imagining the role may clarify why it matters. It does not test Daniel's prepared opening. Use the sentence in the document now, then learn from what was harder than expected."},{id:"manifest-2-perform-opening",text:"Rehearse the first sentence once, type it into the draft, and compare the actual difficulty with expectations.",feedback:"This uses preparation to support an actual move. The typed sentence gives Daniel something to review. Its quality and his discomfort remain open questions, rather than conditions for counting the attempt."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"End useful preparation with a real move. Keep their records separate.",followUp:{questionId:"manifest-2-return",question:"What differed between rehearsing your move and actually doing it?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"What simulation evidence does and does not rank",paragraphs:["Cole and colleagues' 2021 review combined 94 studies, 123 effects, and 5,685 participants. Mental simulation showed an overall behavior effect of g = .49, with a 95% confidence interval from .37 to .62. Most samples were students. Simulations differed in content, dose, and outcome, so the average is not a forecast for your short exercise. [M04]","The review distinguished thinking through process steps from mentally performing a task. Its process-only estimate used five effects and had a confidence interval spanning no effect. The overall subtype comparison was not statistically significant. Higher subgroup averages therefore do not establish a reliable winner. Do not turn a chart into instructions to visualize harder. This lesson uses rehearsal to expose one practical detail, then asks you to attempt the task. Written description is an accessibility choice, not a claim of research-tested equivalence to imagery."]},{heading:"Prepare for an opportunity, then use it",paragraphs:["In the original report-planning experiment, participants pictured a specific time and place for beginning a task. The reported timeliness comparison concerned identifiable returners and a narrow student assignment. It does not establish a universal imagination script or a benefit from rehearsing in bed. [M10] Here, preparation earns its place when it helps you perform the next piece of your existing goal task.","You might notice a missing password, an unclear instruction, or a sentence you cannot yet explain. Resetting a password is preparation; submitting the needed information is task work. Make the distinction visible in your record. Stop bedtime planning if it keeps you awake, and choose a daytime opportunity instead. This is a practical course adaptation. Brief rehearsal is an optional app exercise, not a validated ritual or a condition for beginning. No vivid picture or particular feeling is required."]}],sourceIds:["M04","M10"]}},{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"en",title:"The obstacle is real. Change the conditions",goal:"Use your last attempt to choose and test one feasible obstacle response.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Childcare, missing access, or exhaustion in the way? Believing harder will not rearrange the day.",reason:{id:"manifest-3-reason",label:"What needs support, and what can you change now?",kind:"text",maxLength:160,optional:!0,suggestions:["Shared laptop access needs agreement","I can reduce the résumé edit","Care duties leave no opening today","I have not encountered a barrier yet"]},why:{id:"manifest-3-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Use your same goal and any attempt record. No attempt yet? Name a likely barrier. “No shared computer after dinner” guides a response; “I lack discipline” does not identify the condition.","Studies pairing a desired outcome, a real obstacle, and an if-then response found modest average benefits. They did not establish discomfort as the reason it works. Money, care, time, and access are conditions, not belief defects. Test one change: a smaller task, an available opening, or a specific support request. A request counts as asking, not receiving help."],example:{title:"Daniel changes the opening",text:"Daniel planned another résumé edit after dinner, but his daughter needed the shared laptop for homework. His record names the clash. He asks whether he can use it for ten minutes before dinner the next day. They agree. At that opening he improves one line, then stops. The application still needs work."}},move:{invitation:"Need access? Choose Adapt this, then Support. Name your contact; suggestions show Daniel’s laptop request.",instructions:["Retain your named act, minimum, cue, and place when access is already agreed.","Without access, name the person, resource, and opening in a support request.","Record asking separately from receiving help or completing the task."],prompts:[],suggestions:{action:["Ask daughter for laptop time before dinner","Ask library staff about available computer time"],minimum:["Ask daughter for ten-minute laptop access","Send the library computer-access question"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["When household homework plans are discussed","After lunch today","After dinner is cleared"],place:["At my kitchen table","In the library’s contact form","At the library desk"],minutes:[5,2,10],fallback:["Ask library staff about computer access","Send household member the laptop-time request","Pause until a feasible opening is agreed"],observation:["The access request and any reply","Whether laptop time was actually agreed","Whether I did the named résumé edit"]},suggested:{action:"Ask daughter for laptop time before dinner",minimum:"Ask daughter for ten-minute laptop access",minutes:5,cueHint:"When household homework plans are discussed",placeHint:"At my kitchen table",obstacleHint:"My daughter cannot offer laptop time",fallbackHint:"Ask library staff about computer access",observationHint:"The access request and any reply",kind:"support"},accessibleAlternative:"Type, speak, or use assistance. Choose Adapt for task work after access is agreed.",stopRule:"If the exercise overwhelms you or the setting is unsafe, pause and seek appropriate support."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-3-decision",scenario:"Daniel's evening edits clash with shared-laptop homework. A ten-minute opening before dinner is available if they agree on it.",question:"Which response fits this obstacle?",options:[{id:"manifest-3-arrange-opening",text:"Agree on the available ten-minute opening and use it to improve one line in the same draft.",feedback:"This changes the condition that blocked the task and preserves a useful minimum. Agreement is still needed. Record the request separately if the opening cannot yet be confirmed."},{id:"manifest-3-keep-evening",text:"Keep the evening appointment and add a longer rehearsal so he feels ready when the laptop becomes available.",feedback:"Rehearsal may prepare wording, but it leaves the access clash unchanged. Daniel has a possible alternative opening. Agree on that opening before adding another preparation routine."},{id:"manifest-3-wait-week",text:"Wait until homework demands settle down next week, then restart with the larger résumé session he originally wanted.",feedback:"Waiting can be appropriate when no feasible opening exists. Here, a smaller opening may be arranged now. Test that option instead of postponing all task work automatically."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Name the blocking condition. Change the task or ask for the support it actually needs.",followUp:{questionId:"manifest-3-return",question:"Did you make the access request or task move, and what agreement is still pending?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"An obstacle is information, not an ingredient",paragraphs:["The 2021 mental-contrasting-with-planning review found a modest average improvement in goal attainment across 24 independent effects. Substantial variation and publication-bias indications limit certainty. It did not isolate feeling uncomfortable as an active ingredient. Naming a difficulty may be unpleasant, but deliberately intensifying distress is not the task. [M01]","Oettingen and colleagues' inspected 2015 procedure asked students to elaborate a desired outcome and a main obstacle, select a response, form an obstacle-to-action plan, and add its usual time and place. In Study 1, the planned comparison favored the method for scheduled calendar hours. The outcome was scheduling, not completed work, and the overall condition test was inconclusive. [M11] ODA adds a practical feasibility check and an actual attempt. Neither this shorter exercise nor its distinction between external conditions and personal responses was separately validated by that experiment."]},{heading:"When the right response is support",paragraphs:["Keep your desired outcome separate from the conditions needed to pursue it. A missing tool calls for access; an unsafe situation calls for protection; a care conflict may call for a different opening. This is a course design choice informed by the planning evidence, not a taxonomy that assigns every obstacle to one box. A support request is concrete when it names the help and opportunity you need. [M01, M11]","If someone has not answered, record the request and the absence of a reply. Do not record help received or task work completed. You can choose another feasible step, revise the goal, or pause. For persistent distress or significant impairment, seek qualified support rather than making the exercise more intense. The NIMH help guidance provides care and crisis routes, not evidence that ODA treats a condition. [M14] Your next record should describe the act you chose, including protection or support, without recasting the original obstacle as a failure of belief."]}],sourceIds:["M01","M11","M14"]}},{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"en",title:"Stop waiting for the right mood",goal:"Use a recognizable start cue and a small response to your experiment's observed sticking point.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"“When I feel ready” keeps moving. Choose a moment you can actually notice.",reason:{id:"manifest-4-reason",label:"When the cue last arrived, what did postponing the move cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Compared examples; missed writing","Waited for readiness; left the draft untouched","Care needed me; no safe opening","No prior cue; wording may delay me"],help:"No prior attempt? Name a possible hesitation."},why:{id:"manifest-4-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A start cue and an obstacle response have different jobs. “After the plates are cleared, write one résumé line” creates an opening. “If I get stuck, describe one shift change” helps inside that opening.","Research across varied goals found that specific if-then plans supported follow-through on average. They do not remove all memory, effort, or practical barriers. Keep your task; respond to a recorded obstacle if one exists. Pick one noticeable cue and one response you can carry out there. If the cue never occurs, record no occasion and choose another opening."],example:{title:"Daniel uses the cue",text:"Daniel places a note beside the shared laptop: “After the plates are cleared, improve one line. If stuck, describe one shift change.” On Thursday the cue arrives and he notices the note. He writes one useful line, but cannot finish the section before family duties resume. His record keeps both facts."}},move:{invitation:"Keep your actual task and opening. Suggestions show Daniel’s résumé example.",instructions:["Keep the saved act, minimum, cue, and place unless one needs changing.","Name the smaller response to your actual sticking point before saving."],prompts:[],suggestions:{action:["After dinner, write one résumé scheduling sentence","After lunch, send the résumé-detail question","After tea, correct one résumé date"],minimum:["Save one résumé sentence about scheduling shifts","Send the résumé-detail question","Save one corrected résumé date"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After the plates are cleared","When lunch ends","When I put down my tea"],place:["At my kitchen table","In the résumé document","At the library desk"],minutes:[5,2,10],fallback:["Describe one shift change in one sentence","Choose and name another available opening","Ask library staff about computer access"],observation:["Whether the cue occurred and was noticed","Whether I described the shift change","The résumé change I actually saved"]},suggested:{action:"After dinner, write one résumé scheduling sentence",minimum:"Save one résumé sentence about scheduling shifts",minutes:5,cueHint:"After the plates are cleared",placeHint:"At my kitchen table",obstacleHint:"I reach the cue but get stuck on wording",fallbackHint:"Describe one shift change in one sentence",observationHint:"Whether the cue occurred and was noticed"},accessibleAlternative:"Type, dictate, or use your usual tools; ask for practical assistance if needed.",stopRule:"Keep care and safety obligations; use another opening if this cue becomes unsuitable."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Daniel has five minutes after clearing dinner. His draft and one accurate shift-change example are ready, but he stalls over the wording.",question:"Which plan fits both starting and getting stuck?",options:[{id:"manifest-4-mood-cue",text:"When he feels clearer after dinner, spend five minutes improving the résumé section with his strongest examples.",feedback:"A clearer mood would be welcome, but it is a moving start cue. Use the observable dinner event and a response small enough for the available five minutes."},{id:"manifest-4-full-section",text:"After clearing the plates, compare three scheduling examples before choosing the strongest one for the résumé line.",feedback:"Comparison can improve selection. Daniel already has an accurate example, and searching would consume his five-minute opening. Describe that shift change first; review the wording after a real line exists."},{id:"manifest-4-cue-and-response",text:"After clearing the plates, improve one line; if wording stalls, describe one actual shift change plainly.",feedback:"This gives the opening and the sticking point distinct responses. Daniel can attempt it with his ready draft. The plan supports a move without promising effortless memory or a finished section."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Give starting an opening and getting stuck a response. Then test whether either actually happened.",followUp:{questionId:"manifest-4-return",question:"Did you notice the start cue, and could you use your planned response?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"What specific planning supports",paragraphs:["Gollwitzer and Sheeran's 2006 chapter pooled 94 independent tests with 8,461 participants. If-then planning showed an average goal-attainment effect of d = .65, with a 95% confidence interval from .60 to .70. Tasks and procedures varied, and this older evidence was not uniformly preregistered. It does not establish that any sentence a learner writes will work. [M02]","The opportunity-planning experiment asked students to select a specific time and place to begin a report. Its timeliness comparison concerned identifiable returners, not everyone assigned to the task. [M10] The practical lesson is narrower than “a plan replaces willpower.” Decide a response in advance, then check whether the situation occurred, you noticed it, and the response fit. Keep external reminders if you need them. A note beside a tool is an ODA option, not a tested guarantee of noticing."]},{heading:"Two jobs, one continuing experiment",paragraphs:["Your starting appointment answers when you will attempt the task. Your coping response answers what you will do if an observed obstacle appears. The inspected mental-contrasting procedure linked an obstacle to a response and added its usual time and place; it did not establish that everyone needs two separate rules. [M11] This course separates their jobs to make your existing experiment easier to diagnose.","Suppose the planned opening never arrives. There is no basis for saying the coping response failed. If the opening arrives but you miss it, change the cue or reminder. If you notice it but the response is too large, shrink the next useful task unit. These are choices to test, not findings proven by one private log. Keep old records tied to their original minimum. A different next plan should not turn an incomplete past attempt into completed work. Review your actual move, and retain the option to seek support, rest, pause, or change the goal."]}],sourceIds:["M02","M10","M11"]}},{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"en",title:"No result yet? Read your actual record",goal:"Use your experiment's records to choose a feasible next step and next week's review.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Before you abandon the dream, check whether you tested the route or only kept planning it.",reason:{id:"manifest-5-reason",label:"What would make you keep, change, or stop this route?",kind:"text",maxLength:160,optional:!0,suggestions:["Usable draft; submit it","Repeated clashes; change the opening","Specific feedback; revise the unclear sentence","No attempt yet; choose a first test"]},why:{id:"manifest-5-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Read the records for the same goal. Separate what you planned, rehearsed, actually did, and received from others. A saved draft proves draft work. It does not prove an application was sent or an employer is interested.","A review of 138 experiments found average benefits from increasing progress monitoring. It did not validate this exact record or an ideal review schedule. Choose from your facts: repeat a workable step, change one problem, seek feedback, or stop an unsuitable goal. If no attempt exists, name that gap and make your first useful unit."],example:{title:"Daniel chooses next week",text:"Daniel reads three dated edits and one missed laptop opening. His résumé is clearer, but he has not sent an application. He chooses one suitable vacancy, checks its requirements, and submits the prepared version on Friday. He records the submission and schedules a review next week. There is no reply yet."}},move:{invitation:"Keep what fit; name the next act. Suggestions show a ready application.",instructions:["Keep the saved minimum and appointment when repeating; change only the observed bottleneck.","Without a record, name a first act and matching minimum before saving.","An information request counts as asking, not completion of the blocked task."],prompts:[],suggestions:{action:["Submit the prepared application to the selected vacancy","Ask hiring contact about an unclear requirement","Revise one résumé sentence using reviewer feedback"],minimum:["Send the prepared application once","Send the question about the application requirement","Save the revised résumé sentence"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["When lunch ends","After dinner is cleared","When the vacancy application page opens"],place:["At my kitchen table","At the library desk","In the vacancy’s application form"],minutes:[10,2,5],fallback:["Ask hiring contact about the unclear requirement","Request reviewer feedback on the unclear sentence","Pause until required information is available"],observation:["The submission and its confirmation, if available","The information request and any pending reply","What remains outside my control"]},suggested:{action:"Submit the prepared application to the selected vacancy",minimum:"Send the prepared application once",minutes:10,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"A required application detail is unclear",fallbackHint:"Ask hiring contact about the unclear requirement",observationHint:"The submission and its confirmation, if available"},accessibleAlternative:"Type, dictate, or use your usual tools; ask for practical assistance if needed.",stopRule:"Do not increase spending or sacrifice needed care to rescue an uncertain outcome."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Daniel edited his résumé but has not applied. A suitable vacancy closes tonight. His draft meets its requirements; a reviewer can compare versions tomorrow.",question:"What should his review lead to?",options:[{id:"manifest-5-next-application",text:"Submit the prepared application, record the submission, and choose a later review while the reply remains unknown.",feedback:"The record reveals a concrete next step that is ready and under Daniel's control. Submission is the act. An employer's decision stays unknown until there is actual feedback."},{id:"manifest-5-double-editing",text:"Ask a reviewer to compare two résumé versions before submitting the application, to reduce the chance of weak wording.",feedback:"Comparison could reveal quality problems, but it arrives after tonight’s deadline. Daniel has checked the requirements with no known gap remaining. Submit this suitable version; use later feedback for an actual change."},{id:"manifest-5-change-direction",text:"Use the opening to send several less targeted applications, increasing coverage before deciding which résumé version to keep.",feedback:"Broader coverage can create opportunities. Here one suitable application is already ready. Sending it tests that match; volume can be a later choice without replacing this prepared, targeted submission."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Let records change the next move. Effort, preparation, and outside results tell different stories.",followUp:{questionId:"manifest-5-return",question:"What happened with your chosen task or information request, and what is still pending?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"Monitoring informs a decision",paragraphs:["Harkin and colleagues' 2016 review included 138 experiments with random allocation and 19,951 participants overall. The goal-attainment analysis used 18,398 participants and found d = .40, with a 95% confidence interval from .32 to .48. A small-study sensitivity adjustment gave a lower estimate. Interventions, goals, and recording methods differed. The review did not test ODA's receipt or next-day card. [M03]","Larger effects were associated with recorded or publicly reported progress across studies. Those moderator comparisons do not establish that public disclosure is necessary or that one app format causes a benefit. Keep personal details private if that fits your situation. Use records to compare what the plan asked for with the act you actually reported. An absent record remains unknown. A completed preparation step, unanswered request, or stopped attempt should retain its own label. This makes your next decision reviewable without demanding a positive story."]},{heading:"Choose next week without rewriting this one",paragraphs:["A short personal log can suggest a pattern, but it cannot prove why an outside outcome occurred. Applications, orders, and another person's response may depend on quality, timing, resources, or circumstances your record does not measure. Monitoring research supports using information; it does not establish a universal number of attempts before changing a goal. [M03] Your review should keep that uncertainty visible.","Select one feasible next opportunity and a review point for the coming week. Retain your usable minimum and what helped access the task; change the part your records actually question. If no attempt is recorded, either report known facts or treat the next small act as your first experiment. Do not invent a history of effort. Planning studies show average benefits with variation, not guaranteed outcomes. [M01] Pausing, requesting feedback, finding practical support, or choosing another direction can be a deliberate result of the review. Keep the earlier record so the reason for that choice remains visible."]}],sourceIds:["M03","M01"]}},...a],u={id:"manifest",title:"Dreams going nowhere? Give one wish real work",subtitle:"Five foundation lessons, then 15 popular techniques with honest evidence and a useful action.",description:"Turn one chosen wish into useful work. Keep your experiment through the technique library: learn the rituals, check the research, and try an achievable move.",scope:"Here, manifesting means the practice of intention, preparation and action. The course does not claim that thoughts steer events through quantum effects, that the universe delivers what you focus on, or that any wish is sure to come true. It is not financial, medical or psychological advice.",outcome:"One meaningful goal with a usable minimum, honest attempt records, and a feasible next-week plan.",lessonLibrary:{id:"manifest-technique-library",title:"Technique library",description:"15 familiar rituals. How people do them, what research supports, and an ODA version with action and review.",lessonIds:a.map(e=>e.id),sourceIds:[...n,...i].map(e=>e.id)},photo:{id:"1676782778930-11b311ec5134",alt:"Dirt road climbing a grassy hill toward distant mountains"},lessons:[{id:"manifest-1",v2:t[0],photo:{id:"1768055104910-8c8d213835fb",alt:"Hand writing a to-do list in a notebook"},schemaVersion:2,title:"Dream still waiting? Make one useful thing",minutes:6,goal:"Produce one usable piece of work for a goal you choose.",reading:["A better job is an outcome. Improving one résumé line is a behavior. Other people still decide whether to call. Choose work worth doing without making their reply the test of your effort.","In one student experiment, selecting a starting time and place improved timeliness among people who returned a report. It did not increase overall cooperation. A plan can support starting; it cannot guarantee results. Choose one usable line, answer, or request today. Keep this goal through the course, and bring back what actually happened."],practice:["Write or think of one wish that matters to you, in a single sentence.","Choose one behavior within your control that moves you toward that wish.","Describe the behavior with a small finish line, for example “three lines of a draft”."],reflection:"What is today’s behavior version of your wish?",question:"Which of these is a behavior you can choose directly?",options:["The employer definitely choosing me.","Editing three lines of my résumé tomorrow.","Nothing going wrong at all."],correct:1,feedback:"You cannot guarantee other people’s decisions. You can make your own preparation concrete.",takeaway:"Give the wish a useful act. Record the act separately from the answer you hope for.",sources:["M10","M01","M07"],deeper:[{heading:"What a starting plan can support",paragraphs:["Gollwitzer and Brandstätter's 1997 Study 2 assigned 86 Munich students a report about Christmas. Planners chose an exact time and place, pictured that opportunity, committed to starting, and recorded those choices. Among the 36 identifiable report returners, 12 of 17 planners and six of 19 controls wrote within the requested two days. Those percentages describe returners, not everyone recruited. Planning did not increase overall cooperation. [M10]","The lesson borrows the concrete opportunity, then asks for usable work at that opportunity. That general-purpose adaptation was not tested in the Christmas-report study. A date alone does not tell you where the time will come from. Use an event you can recognize and a place you can access. If the resources are missing, asking for them can be the actual move. Record that request as a request, even when help has not arrived."]},{heading:"A wish does not control other people",paragraphs:["Wang and colleagues' 2021 review pooled 24 independent effects from 21 articles, with 15,907 participants. Pairing a desired outcome with an obstacle and an if-then response showed a modest average goal-attainment benefit: g = .336, with a 95% confidence interval from .229 to .443. Findings varied substantially, and a publication-bias adjustment reduced the estimate. This supports bounded planning, not a promise for this course. [M01]","Dixon and colleagues studied manifestation beliefs in three US online surveys totaling 1,023 participants. Belief correlated with some financial-risk reports and reported bankruptcy, but not reported income or education. These associations do not show that belief caused bankruptcy or objectively test every manifestation exercise. [M07] Use your wish to choose work and assess constraints. Do not infer that thoughts attracted an opportunity, caused hardship, or made you deserve an outcome. Money, care, access, and other people's decisions still matter."]}],example:{title:"Daniel makes a start",text:"At the kitchen table after dinner, Daniel gives his logistics-job goal ten minutes. He rewrites one résumé line to describe scheduling eight warehouse shifts. The wording still feels clumsy. He saves it anyway and records the change. No employer has seen it yet. Tomorrow he can improve a real draft."}},{id:"manifest-2",v2:t[1],photo:{id:"1517363898874-737b62a7db91",alt:"Person sitting quietly by a window in warm light"},schemaVersion:2,title:"Rehearsing again? Give the scene an ending",minutes:6,goal:"Rehearse one sticking point, then produce the next usable part of your existing goal task.",reading:["Retrieve your chosen task and any record. Rehearsing means mentally doing a particular move, such as saying the first sentence. Listing steps is a different kind of preparation. Neither is the real attempt.","A review found average behavior benefits from mental simulation, but did not establish a best subtype. It does not prove that this brief rehearsal works. Use it only to identify your sticking point and a response. Describe the move in words if pictures do not come. Then make the next usable line in the same task."],practice:["Name one difference you want your goal to make in your life.","Put your first two moves in order, as images or as words.","After the rehearsal, actually do one preparation step."],reflection:"Which missing preparation did you notice during the rehearsal?",question:"What does mental rehearsal mean in this course?",options:["An exercise that prepares you for real action.","Controlling outside events for certain with your thoughts.","No longer needing to try at all."],correct:0,feedback:"Rehearsal is preparation. The cited studies do not validate this exact brief exercise or show that it controls external outcomes. Use preparation to support a real move.",takeaway:"End useful preparation with a real move. Keep their records separate.",sources:["M04","M10"],deeper:[{heading:"What simulation evidence does and does not rank",paragraphs:["Cole and colleagues' 2021 review combined 94 studies, 123 effects, and 5,685 participants. Mental simulation showed an overall behavior effect of g = .49, with a 95% confidence interval from .37 to .62. Most samples were students. Simulations differed in content, dose, and outcome, so the average is not a forecast for your short exercise. [M04]","The review distinguished thinking through process steps from mentally performing a task. Its process-only estimate used five effects and had a confidence interval spanning no effect. The overall subtype comparison was not statistically significant. Higher subgroup averages therefore do not establish a reliable winner. Do not turn a chart into instructions to visualize harder. This lesson uses rehearsal to expose one practical detail, then asks you to attempt the task. Written description is an accessibility choice, not a claim of research-tested equivalence to imagery."]},{heading:"Prepare for an opportunity, then use it",paragraphs:["In the original report-planning experiment, participants pictured a specific time and place for beginning a task. The reported timeliness comparison concerned identifiable returners and a narrow student assignment. It does not establish a universal imagination script or a benefit from rehearsing in bed. [M10] Here, preparation earns its place when it helps you perform the next piece of your existing goal task.","You might notice a missing password, an unclear instruction, or a sentence you cannot yet explain. Resetting a password is preparation; submitting the needed information is task work. Make the distinction visible in your record. Stop bedtime planning if it keeps you awake, and choose a daytime opportunity instead. This is a practical course adaptation. Brief rehearsal is an optional app exercise, not a validated ritual or a condition for beginning. No vivid picture or particular feeling is required."]}],example:{title:"Daniel meets the blank line",text:"Daniel returns to his résumé after dinner. For thirty seconds he rehearses describing a difficult scheduling change. He expects to freeze, so he practices starting with “Changed eight shifts when…” Then he types a usable sentence. He deletes two words and leaves a question for feedback. The rehearsal missed how much detail he needed."}},{id:"manifest-3",v2:t[2],photo:{id:"1767134063671-322e6faf9206",alt:"Fallen tree lying across a leafy forest path"},schemaVersion:2,title:"The obstacle is real. Change the conditions",minutes:6,goal:"Use your last attempt to choose and test one feasible obstacle response.",reading:["Use your same goal and any attempt record. No attempt yet? Name a likely barrier. “No shared computer after dinner” guides a response; “I lack discipline” does not identify the condition.","Studies pairing a desired outcome, a real obstacle, and an if-then response found modest average benefits. They did not establish discomfort as the reason it works. Money, care, time, and access are conditions, not belief defects. Test one change: a smaller task, an available opening, or a specific support request. A request counts as asking, not receiving help."],practice:["Name the nearest obstacle standing in front of your goal.","Separate the part of the obstacle you can influence from the part that needs support or time.","If it cannot be done right now, make the goal smaller or move it to a suitable time."],reflection:"Looking at your obstacle more realistically, what changed in your plan?",question:"When outside conditions get in the way…",options:["I should assume it is because I did not believe enough.","I should ignore the conditions.","I can reconsider support, timing or the size of the goal."],correct:2,feedback:"A realistic plan takes outside conditions into account. Outcomes are not decided by your thoughts alone.",takeaway:"Name the blocking condition. Change the task or ask for the support it actually needs.",sources:["M01","M11","M14"],deeper:[{heading:"An obstacle is information, not an ingredient",paragraphs:["The 2021 mental-contrasting-with-planning review found a modest average improvement in goal attainment across 24 independent effects. Substantial variation and publication-bias indications limit certainty. It did not isolate feeling uncomfortable as an active ingredient. Naming a difficulty may be unpleasant, but deliberately intensifying distress is not the task. [M01]","Oettingen and colleagues' inspected 2015 procedure asked students to elaborate a desired outcome and a main obstacle, select a response, form an obstacle-to-action plan, and add its usual time and place. In Study 1, the planned comparison favored the method for scheduled calendar hours. The outcome was scheduling, not completed work, and the overall condition test was inconclusive. [M11] ODA adds a practical feasibility check and an actual attempt. Neither this shorter exercise nor its distinction between external conditions and personal responses was separately validated by that experiment."]},{heading:"When the right response is support",paragraphs:["Keep your desired outcome separate from the conditions needed to pursue it. A missing tool calls for access; an unsafe situation calls for protection; a care conflict may call for a different opening. This is a course design choice informed by the planning evidence, not a taxonomy that assigns every obstacle to one box. A support request is concrete when it names the help and opportunity you need. [M01, M11]","If someone has not answered, record the request and the absence of a reply. Do not record help received or task work completed. You can choose another feasible step, revise the goal, or pause. For persistent distress or significant impairment, seek qualified support rather than making the exercise more intense. The NIMH help guidance provides care and crisis routes, not evidence that ODA treats a condition. [M14] Your next record should describe the act you chose, including protection or support, without recasting the original obstacle as a failure of belief."]}],example:{title:"Daniel changes the opening",text:"Daniel planned another résumé edit after dinner, but his daughter needed the shared laptop for homework. His record names the clash. He asks whether he can use it for ten minutes before dinner the next day. They agree. At that opening he improves one line, then stops. The application still needs work."}},{id:"manifest-4",v2:t[3],photo:{id:"1591462391971-9ffc57b382b9",alt:"Colorful sticky notes and pens"},schemaVersion:2,title:"Stop waiting for the right mood",minutes:6,goal:"Use a recognizable start cue and a small response to your experiment's observed sticking point.",reading:["A start cue and an obstacle response have different jobs. “After the plates are cleared, write one résumé line” creates an opening. “If I get stuck, describe one shift change” helps inside that opening.","Research across varied goals found that specific if-then plans supported follow-through on average. They do not remove all memory, effort, or practical barriers. Keep your task; respond to a recorded obstacle if one exists. Pick one noticeable cue and one response you can carry out there. If the cue never occurs, record no occasion and choose another opening."],practice:["Describe one obstacle signal in the form “If …”.","In the “then …” part, write a single small behavior.","Check that the plan fits the time and tools you have, then rehearse it once."],reflection:"What is your if-then sentence?",question:"Which plan can actually be tried?",options:["Everything will sort itself out.","If I get stuck when I open the file, I will write the title first.","If I send good energy, all the obstacles will disappear."],correct:1,feedback:"The second option links a specific situation to an observable behavior. The approach studied in research looks like this kind of action planning.",takeaway:"Give starting an opening and getting stuck a response. Then test whether either actually happened.",sources:["M02","M10","M11"],deeper:[{heading:"What specific planning supports",paragraphs:["Gollwitzer and Sheeran's 2006 chapter pooled 94 independent tests with 8,461 participants. If-then planning showed an average goal-attainment effect of d = .65, with a 95% confidence interval from .60 to .70. Tasks and procedures varied, and this older evidence was not uniformly preregistered. It does not establish that any sentence a learner writes will work. [M02]","The opportunity-planning experiment asked students to select a specific time and place to begin a report. Its timeliness comparison concerned identifiable returners, not everyone assigned to the task. [M10] The practical lesson is narrower than “a plan replaces willpower.” Decide a response in advance, then check whether the situation occurred, you noticed it, and the response fit. Keep external reminders if you need them. A note beside a tool is an ODA option, not a tested guarantee of noticing."]},{heading:"Two jobs, one continuing experiment",paragraphs:["Your starting appointment answers when you will attempt the task. Your coping response answers what you will do if an observed obstacle appears. The inspected mental-contrasting procedure linked an obstacle to a response and added its usual time and place; it did not establish that everyone needs two separate rules. [M11] This course separates their jobs to make your existing experiment easier to diagnose.","Suppose the planned opening never arrives. There is no basis for saying the coping response failed. If the opening arrives but you miss it, change the cue or reminder. If you notice it but the response is too large, shrink the next useful task unit. These are choices to test, not findings proven by one private log. Keep old records tied to their original minimum. A different next plan should not turn an incomplete past attempt into completed work. Review your actual move, and retain the option to seek support, rest, pause, or change the goal."]}],example:{title:"Daniel uses the cue",text:"Daniel places a note beside the shared laptop: “After the plates are cleared, improve one line. If stuck, describe one shift change.” On Thursday the cue arrives and he notices the note. He writes one useful line, but cannot finish the section before family duties resume. His record keeps both facts."}},{id:"manifest-5",v2:t[4],photo:{id:"1762920738995-f393efe82205",alt:"Wooden signpost pointing in several directions in a forest"},schemaVersion:2,title:"No result yet? Read your actual record",minutes:6,goal:"Use your experiment's records to choose a feasible next step and next week's review.",reading:["Read the records for the same goal. Separate what you planned, rehearsed, actually did, and received from others. A saved draft proves draft work. It does not prove an application was sent or an employer is interested.","A review of 138 experiments found average benefits from increasing progress monitoring. It did not validate this exact record or an ideal review schedule. Choose from your facts: repeat a workable step, change one problem, seek feedback, or stop an unsuitable goal. If no attempt exists, name that gap and make your first useful unit."],practice:["Do your first small attempt, or fix exactly when you will do it.","Set a reasonable date to check the result, and use the questions “What did I try, and what did I learn?”","Choose what fits best: continue, make it smaller, get support, or change the goal."],reflection:"On which day, and looking at which information, will you review your plan?",question:"When the result you wanted does not come, what is the most useful review?",options:["My thoughts were not strong enough.","Looking at the behaviors I tried and the conditions, then making the next choice.","Keeping the same expectation without looking at reality."],correct:1,feedback:"Comparing the plan with reality gives you new information. No course guarantees a result; you can weigh your own part and the outside conditions together.",takeaway:"Let records change the next move. Effort, preparation, and outside results tell different stories.",sources:["M03","M01"],deeper:[{heading:"Monitoring informs a decision",paragraphs:["Harkin and colleagues' 2016 review included 138 experiments with random allocation and 19,951 participants overall. The goal-attainment analysis used 18,398 participants and found d = .40, with a 95% confidence interval from .32 to .48. A small-study sensitivity adjustment gave a lower estimate. Interventions, goals, and recording methods differed. The review did not test ODA's receipt or next-day card. [M03]","Larger effects were associated with recorded or publicly reported progress across studies. Those moderator comparisons do not establish that public disclosure is necessary or that one app format causes a benefit. Keep personal details private if that fits your situation. Use records to compare what the plan asked for with the act you actually reported. An absent record remains unknown. A completed preparation step, unanswered request, or stopped attempt should retain its own label. This makes your next decision reviewable without demanding a positive story."]},{heading:"Choose next week without rewriting this one",paragraphs:["A short personal log can suggest a pattern, but it cannot prove why an outside outcome occurred. Applications, orders, and another person's response may depend on quality, timing, resources, or circumstances your record does not measure. Monitoring research supports using information; it does not establish a universal number of attempts before changing a goal. [M03] Your review should keep that uncertainty visible.","Select one feasible next opportunity and a review point for the coming week. Retain your usable minimum and what helped access the task; change the part your records actually question. If no attempt is recorded, either report known facts or treat the next small act as your first experiment. Do not invent a history of effort. Planning studies show average benefits with variation, not guaranteed outcomes. [M01] Pausing, requesting feedback, finding practical support, or choosing another direction can be a deliberate result of the review. Keep the earlier record so the reason for that choice remains visible."]}],example:{title:"Daniel chooses next week",text:"Daniel reads three dated edits and one missed laptop opening. His résumé is clearer, but he has not sent an application. He chooses one suitable vacancy, checks its requirements, and submits the prepared version on Friday. He records the submission and schedules a review next week. There is no reply yet."}},...a.map(r)]};export{u as COURSE,t as MANIFEST_LESSONS_V2,p as SOURCES};
